window.KotobaRegionalAdditions=[{"region":"hakodate","phrase":"お茶碗をうるかす","reading":"Ochawan o urukasu","standard":"お茶碗を水に浸してふやかす","english":"Soak the rice bowl.","scene":"家事・食器洗い","sceneEn":"Housework · washing dishes","tag":"cleanup","register":"regional","registerEn":"regional","example":"A: ご飯がこびりついているね。 B: 先にお茶碗をうるかすね。","exampleEn":"A: Rice is stuck to the bowl. B: I’ll soak it first.","note":"「うるかす」は水に浸してふやかすこと。函館校の記録。","noteEn":"Urukasu means soaking to soften; documented in the Hakodate column.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"コートの雪をほろう","reading":"Kōto no yuki o horou","standard":"コートの雪を払い落とす","english":"Brush the snow off the coat.","scene":"玄関・冬","sceneEn":"Entryway · winter","tag":"action","register":"regional","registerEn":"regional","example":"A: コートに雪がついているよ。 B: 玄関で雪をほろうね。","exampleEn":"A: There’s snow on your coat. B: I’ll brush it off at the entrance.","note":"「ほろう」は付いた雪などを払うこと。道内での用例。","noteEn":"Horou means brushing off snow or similar material; documented for Hokkaido.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"今朝はしばれるね","reading":"Kesa wa shibareru ne","standard":"今朝は凍てつくほど寒いね","english":"It is bitterly cold this morning.","scene":"天気・朝","sceneEn":"Weather · morning","tag":"condition","register":"regional","registerEn":"regional","example":"A: 窓の外が真っ白だね。 B: 今朝はしばれるね。","exampleEn":"A: Everything outside is white. B: It’s bitterly cold this morning.","note":"「しばれる」は凍てつくような厳しい寒さを表すことば。","noteEn":"Shibareru describes severe, freezing cold.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"せばね、来週会おう","reading":"Seba ne, raishū aō","standard":"じゃあね、来週会おう","english":"See you; let’s meet next week.","scene":"友だち・別れ","sceneEn":"Friends · farewell","tag":"farewell","register":"regional","registerEn":"regional","example":"A: 今日は楽しかった。 B: せばね、来週会おう。","exampleEn":"A: Today was fun. B: See you; let’s meet next week.","note":"「せばね」は函館で記録された別れの挨拶。世代差もある。","noteEn":"Seba ne is a farewell recorded in Hakodate; use varies by generation.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"はんかくさい失敗をした","reading":"Hankakusai shippai o shita","standard":"ばかばかしい失敗をした","english":"I made a foolish mistake.","scene":"日常・失敗","sceneEn":"Daily life · mistakes","tag":"reaction","register":"regional","registerEn":"regional","example":"A: 家に財布を忘れた。 B: 私もはんかくさい失敗をしたよ。","exampleEn":"A: I left my wallet at home. B: I made a foolish mistake too.","note":"「はんかくさい」は愚かだという評価。強い叱責にもなる。","noteEn":"Hankakusai means foolish; it can also be a strong rebuke.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"このご飯、あめているね","reading":"Kono gohan, amete iru ne","standard":"このご飯、傷んでいるね","english":"This rice has spoiled.","scene":"台所・食べ物","sceneEn":"Kitchen · food","tag":"food","register":"regional","registerEn":"regional","example":"A: このご飯、においが違うね。 B: あめているね。","exampleEn":"A: This rice smells different. B: It has spoiled.","note":"「あめる」は食べ物が傷むこと。函館校で紹介されている。","noteEn":"Ameru means food spoiling; documented in the Hakodate column.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"おばんでした","reading":"Oban deshita","standard":"こんばんは","english":"Good evening.","scene":"近所・夜の挨拶","sceneEn":"Neighborhood · evening greeting","tag":"greeting","register":"regional","registerEn":"regional","example":"A: おばんでした。 B: こんばんは、お帰りですか。","exampleEn":"A: Good evening. B: Good evening; are you heading home?","note":"「おばんでした」は過去形の形でも、夜の挨拶として使う。","noteEn":"Oban deshita is an evening greeting despite its past-tense form.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"手袋をはくね","reading":"Tebukuro o haku ne","standard":"手袋をはめるね","english":"I’ll put on my gloves.","scene":"冬・身支度","sceneEn":"Winter · getting ready","tag":"action","register":"regional","registerEn":"regional","example":"A: 手が冷たくなった。 B: 私は手袋をはくね。","exampleEn":"A: My hands are cold. B: I’ll put on my gloves.","note":"北海道の用法では、手袋を身につけることも「はく」という。","noteEn":"In this Hokkaido usage, haku also means putting on gloves.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"玄関の鍵をかるね","reading":"Genkan no kagi o karu ne","standard":"玄関の鍵をかけるね","english":"I’ll lock the front door.","scene":"外出・戸締まり","sceneEn":"Going out · locking up","tag":"action","register":"regional","registerEn":"regional","example":"A: もう出発できる？ B: 玄関の鍵をかるね。","exampleEn":"A: Are we ready to leave? B: I’ll lock the front door.","note":"「鍵をかる」は鍵をかけること。「買う」とは意味が異なる。","noteEn":"Kagi o karu means locking up, distinct from buying a key.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"じょっぴんかるね","reading":"Joppin karu ne","standard":"鍵をかけるね","english":"I’ll lock up.","scene":"外出・戸締まり","sceneEn":"Going out · locking up","tag":"action","register":"regional","registerEn":"regional","example":"A: 準備はできた？ B: 最後にじょっぴんかるね。","exampleEn":"A: Are you ready? B: I’ll lock up as the last step.","note":"「じょっぴん」は鍵。「じょっぴんかる」は鍵をかけること。","noteEn":"Joppin means lock; joppin karu means lock up.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"机の上がわやだ","reading":"Tsukue no ue ga waya da","standard":"机の上がめちゃくちゃだ","english":"The desktop is a mess.","scene":"机・片づけ","sceneEn":"Desk · tidying","tag":"status","register":"regional","registerEn":"regional","example":"A: 書類が山になっているね。 B: 机の上がわやだ。","exampleEn":"A: The papers are piled up. B: The desktop is a mess.","note":"「わや」は文脈で評価が変わる。ここでは乱雑な状態の意味。","noteEn":"Waya changes with context; here it describes a messy state.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"なしたの？","reading":"Nashita no?","standard":"どうしたの？","english":"What happened?","scene":"友だち・声かけ","sceneEn":"Friends · checking in","tag":"question","register":"regional","registerEn":"regional","example":"A: なしたの？ B: 大事なノートを忘れたんだ。","exampleEn":"A: What happened? B: I forgot an important notebook.","note":"「なした？」は様子の違う相手に「どうしたの」と尋ねる語。","noteEn":"Nashita asks what happened when someone seems different.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"なして、その色にしたの？","reading":"Nashite, sono iro ni shita no?","standard":"どうして、その色にしたの？","english":"Why did you choose that color?","scene":"買い物・選択","sceneEn":"Shopping · choices","tag":"question","register":"regional","registerEn":"regional","example":"A: 青いノートにしたよ。 B: なして、その色にしたの？","exampleEn":"A: I chose a blue notebook. B: Why did you choose that color?","note":"「なして」は理由を尋ねる「どうして」。函館校の用例。","noteEn":"Nashite means why; documented in the Hakodate column.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"なしても、この絵を見たい","reading":"Nashitemo, kono e o mitai","standard":"どうしても、この絵を見たい","english":"I really want to see this painting.","scene":"旅行・美術館","sceneEn":"Travel · art museum","tag":"decision","register":"regional","registerEn":"regional","example":"A: 美術館に寄る？ B: なしても、この絵を見たい。","exampleEn":"A: Shall we stop at the museum? B: I really want to see this painting.","note":"「なしても」は「どうしても」の意味。函館校での記録語。","noteEn":"Nashitemo means by all means or really; documented in the column.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"なんもなんも","reading":"Nanmo nanmo","standard":"どういたしまして／気にしないで","english":"You’re welcome; don’t worry about it.","scene":"友だち・お礼への返事","sceneEn":"Friends · responding to thanks","tag":"reassurance","register":"regional","registerEn":"regional","example":"A: 傘を貸してくれてありがとう。 B: なんもなんも。","exampleEn":"A: Thanks for lending me your umbrella. B: You’re welcome.","note":"お礼への返事の「なんも」は、気にしないでという意味。","noteEn":"As a reply to thanks, nanmo means don’t worry about it.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"hakodate","phrase":"この紙は投げるね","reading":"Kono kami wa nageru ne","standard":"この紙は捨てるね","english":"I’ll throw this paper away.","scene":"家事・ごみ分別","sceneEn":"Housework · sorting rubbish","tag":"cleanup","register":"regional","registerEn":"regional","example":"A: その紙、もう使う？ B: 使わないから投げるね。","exampleEn":"A: Will you use that paper again? B: No, so I’ll throw it away.","note":"ごみを「投げる」は捨てるという意味。放り投げる指示ではない。","noteEn":"For rubbish, nageru means dispose of it, not toss it through the air.","sourceUrl":"https://www.hokkyodai.ac.jp/info_topics_hue/hak/detail/10406.html","sourceTitle":"北海道教育大学函館校「函館弁・北海道弁講座」2020–2021"},{"region":"yamagata","phrase":"あでくらをしよう","reading":"Adekura o shiyō","standard":"雪合戦をしよう","english":"Let’s have a snowball fight.","scene":"遊び・雪","sceneEn":"Play · snow","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 雪が積もったね。 B: 庭であでくらをしよう。","exampleEn":"A: The snow has settled. B: Let’s have a snowball fight in the garden.","note":"「あでくら」は雪合戦。南山形の記録語で、世代差がある。","noteEn":"Adekura means snowball fight; recorded in South Yamagata, with age variation.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"あどつぁまに花を供える","reading":"Adotsama ni hana o sonaeru","standard":"仏壇に花を供える","english":"Place flowers at the household Buddhist altar.","scene":"家・行事","sceneEn":"Home · family observances","tag":"daily","register":"regional","registerEn":"regional","example":"A: この花はどこに置く？ B: あどつぁまに供えよう。","exampleEn":"A: Where should we put these flowers? B: Let’s place them at the family altar.","note":"「あどつぁま」は仏壇。南山形で採録された地域のことば。","noteEn":"Adotsama means a household Buddhist altar; recorded in South Yamagata.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"いれぽこに入れたよ","reading":"Irepoko ni ireta yo","standard":"ポケットに入れたよ","english":"I put it in my pocket.","scene":"外出・持ち物","sceneEn":"Going out · belongings","tag":"status","register":"regional","registerEn":"regional","example":"A: 切符はどこ？ B: いれぽこに入れたよ。","exampleEn":"A: Where is the ticket? B: I put it in my pocket.","note":"「いれぽこ」は服のポケット。南山形のことば集にある語。","noteEn":"Irepoko means a clothing pocket; listed in the South Yamagata collection.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"今日は人がうがえね","reading":"Kyō wa hito ga ugae ne","standard":"今日は人が多いね","english":"There are many people today.","scene":"買い物・混雑","sceneEn":"Shopping · crowds","tag":"quantity","register":"regional","registerEn":"regional","example":"A: 商店街がにぎやかだね。 B: 今日は人がうがえね。","exampleEn":"A: The shopping street is lively. B: There are many people today.","note":"「うがえ」は多いの意味。南山形の記録で、地域差もある。","noteEn":"Ugae means many; recorded locally in South Yamagata.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"うずで待っているね","reading":"Uzu de matte iru ne","standard":"家で待っているね","english":"I’ll wait at home.","scene":"待ち合わせ・家","sceneEn":"Meeting up · home","tag":"daily","register":"regional","registerEn":"regional","example":"A: 荷物を届けに行くよ。 B: うずで待っているね。","exampleEn":"A: I’ll bring the parcel over. B: I’ll wait at home.","note":"「うず」は家のこと。南山形の採録語として意味を覚える。","noteEn":"Uzu means home or house; recorded in South Yamagata.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"この花はうずぐさえね","reading":"Kono hana wa uzugusae ne","standard":"この花は美しいね","english":"This flower is beautiful.","scene":"庭・花","sceneEn":"Garden · flowers","tag":"compliment","register":"regional","registerEn":"regional","example":"A: 庭の花が咲いたよ。 B: この花はうずぐさえね。","exampleEn":"A: The garden flowers have bloomed. B: This flower is beautiful.","note":"「うずぐさえ」は美しいという意味。南山形の地域の記録。","noteEn":"Uzugusae means beautiful; recorded in the South Yamagata district.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"えづのこまえ、雨が止んだね","reading":"Ezunokomae, ame ga yanda ne","standard":"いつの間にか、雨が止んだね","english":"The rain stopped without us noticing.","scene":"天気・変化","sceneEn":"Weather · changes","tag":"reaction","register":"regional","registerEn":"regional","example":"A: 外が明るいね。 B: えづのこまえ、雨が止んだね。","exampleEn":"A: It’s bright outside. B: The rain stopped without us noticing.","note":"「えづのこまえ」はいつの間にか。南山形のことば集の語。","noteEn":"Ezunokomae means without noticing when; listed in the local collection.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"絵本がえっぱえある","reading":"Ehon ga eppae aru","standard":"絵本がたくさんある","english":"There are lots of picture books.","scene":"図書館・本","sceneEn":"Library · books","tag":"quantity","register":"regional","registerEn":"regional","example":"A: ここは児童書の棚だよ。 B: 絵本がえっぱえあるね。","exampleEn":"A: This is the children’s section. B: There are lots of picture books.","note":"「えっぱえ」はたくさんの意味。南山形で採録された語。","noteEn":"Eppae means a lot; recorded in South Yamagata.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"今日のおさえは何？","reading":"Kyō no osae wa nani?","standard":"今日のおかずは何？","english":"What is today’s side dish?","scene":"食事・献立","sceneEn":"Meals · menu","tag":"food","register":"regional","registerEn":"regional","example":"A: 今日のおさえは何？ B: 焼き魚とサラダだよ。","exampleEn":"A: What is today’s side dish? B: Grilled fish and salad.","note":"「おさえ」はおかず。南山形の記録語で、使用には世代差。","noteEn":"Osae means side dishes; recorded locally, with generational differences.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"使い方をおしぇるね","reading":"Tsukaikata o osheru ne","standard":"使い方を教えるね","english":"I’ll show you how to use it.","scene":"学習・道具","sceneEn":"Learning · tools","tag":"instruction","register":"regional","registerEn":"regional","example":"A: この道具は初めて使う。 B: 使い方をおしぇるね。","exampleEn":"A: I’ve never used this tool. B: I’ll show you how to use it.","note":"「おしぇる」は教える。南山形では告げ口する意味も記録。","noteEn":"Osheru means teach; the local collection also records tell on someone.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"乾いた小枝をおだる","reading":"Kawaita koeda o odaru","standard":"乾いた小枝を折る","english":"Break a dry twig.","scene":"工作・材料","sceneEn":"Crafts · materials","tag":"action","register":"regional","registerEn":"regional","example":"A: この枝は長すぎるね。 B: 乾いた小枝をおだるよ。","exampleEn":"A: This twig is too long. B: I’ll break the dry twig.","note":"「おだる」は折るの意味。南山形で採録された地域の語。","noteEn":"Odaru means oru, break; recorded in South Yamagata.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"yamagata","phrase":"おづげもあるよ","reading":"Ozuge mo aru yo","standard":"みそ汁もあるよ","english":"There is miso soup too.","scene":"食事・配膳","sceneEn":"Meals · serving","tag":"food","register":"regional","registerEn":"regional","example":"A: ご飯をよそったよ。 B: おづげもあるよ。","exampleEn":"A: I’ve served the rice. B: There’s miso soup too.","note":"「おづげ」は食事のお汁、みそ汁。南山形のことば集の語。","noteEn":"Ozuge means soup served with a meal, including miso soup; recorded locally.","sourceUrl":"https://www.t-bunkyo.ac.jp/minamiyamagata/upload/pdf/minamiyamagata_sassi.pdf","sourceTitle":"東北文教大学短期大学部・南山形コミュニティーセンター「南山形ことば集」2012"},{"region":"ibaraki","phrase":"あーれに置いて","reading":"Āre ni oite","standard":"あそこに置いて","english":"Put it over there.","scene":"片づけ・置き場所","sceneEn":"Tidying · placement","tag":"request","register":"regional","registerEn":"regional","example":"A: この箱、どこに置く？ B: あーれに置いて。","exampleEn":"A: Where should I put this box? B: Put it over there.","note":"「あーれ」はあそこ。茨城県北の大子町の辞書にある語。","noteEn":"Āre means over there; listed in the Daigo Town dictionary in northern Ibaraki.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"青なじみになった","reading":"Aonajimi ni natta","standard":"青あざになった","english":"It left a bruise.","scene":"日常・体のこと","sceneEn":"Daily life · the body","tag":"body","register":"regional","registerEn":"regional","example":"A: 机にぶつけたところは？ B: 青なじみになったよ。","exampleEn":"A: What happened where you bumped the desk? B: It left a bruise.","note":"「青なじみ」は青あざ。大子町の辞書で確認できる語。","noteEn":"Aonajimi means a bruise; documented in the Daigo Town dictionary.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"猫のあしとがある","reading":"Neko no ashito ga aru","standard":"猫の足跡がある","english":"There are cat pawprints.","scene":"庭・動物","sceneEn":"Garden · animals","tag":"animal","register":"regional","registerEn":"regional","example":"A: 土の上に何かあるよ。 B: 猫のあしとだね。","exampleEn":"A: There are marks in the soil. B: They’re cat pawprints.","note":"「あしと」は足跡。ここでは大子町で記録された意味。","noteEn":"Ashito means footprints; this entry follows the Daigo Town record.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"この毛布はあつっこいね","reading":"Kono mōfu wa atsukkoi ne","standard":"この毛布は厚いね","english":"This blanket is thick.","scene":"家・寝具","sceneEn":"Home · bedding","tag":"adjective","register":"regional","registerEn":"regional","example":"A: 新しい毛布を出したよ。 B: この毛布はあつっこいね。","exampleEn":"A: I brought out a new blanket. B: This blanket is thick.","note":"「あつっこい」は厚いの意味。大子町の方言辞書に掲載。","noteEn":"Atsukkoi means thick; listed in the Daigo Town dialect dictionary.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"あっためげえしを見ている","reading":"Attamegēshi o mite iru","standard":"再放送を見ている","english":"I’m watching a rerun.","scene":"家・テレビ","sceneEn":"Home · television","tag":"daily","register":"regional","registerEn":"regional","example":"A: この番組、前にも見た？ B: 今日はあっためげえしを見ているよ。","exampleEn":"A: Have you seen this show before? B: Today I’m watching a rerun.","note":"「あっためげえし」は再放送。大子町で記録されたことば。","noteEn":"Attamegēshi means rerun or rebroadcast; recorded in Daigo Town.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"あっぱとっぱしていた","reading":"Appatoppa shite ita","standard":"あたふたしていた","english":"I was flustered.","scene":"準備・急な予定","sceneEn":"Preparation · sudden plans","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 今朝は急いでいたね。 B: 出発時間を間違えて、あっぱとっぱしていた。","exampleEn":"A: You were rushing this morning. B: I had the departure time wrong and was flustered.","note":"「あっぱとっぱ」はあたふたする様子。大子町の記録語。","noteEn":"Appatoppa describes being flustered; recorded in Daigo Town.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"ありんどめがいるね","reading":"Arindome ga iru ne","standard":"アリがいるね","english":"There are ants.","scene":"庭・小さな生き物","sceneEn":"Garden · small creatures","tag":"animal","register":"regional","registerEn":"regional","example":"A: 花壇の土を見て。 B: ありんどめがいるね。","exampleEn":"A: Look at the soil in the flowerbed. B: There are ants.","note":"「ありんどめ」はアリのこと。大子町の辞書での採録語。","noteEn":"Arindome means ant; listed in the Daigo Town dictionary.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"あんにぃと出かける","reading":"Annii to dekakeru","standard":"兄と出かける","english":"I’m going out with my older brother.","scene":"家族・外出","sceneEn":"Family · going out","tag":"daily","register":"regional","registerEn":"regional","example":"A: 誰と買い物に行くの？ B: あんにぃと出かけるよ。","exampleEn":"A: Who are you shopping with? B: I’m going out with my older brother.","note":"「あんにぃ」は兄。茨城県北の大子町の辞書にある呼び方。","noteEn":"Annii means older brother; documented in Daigo Town in northern Ibaraki.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"いがいかぼちゃだね","reading":"Igai kabocha da ne","standard":"大きいかぼちゃだね","english":"That is a big pumpkin.","scene":"買い物・野菜","sceneEn":"Shopping · vegetables","tag":"adjective","register":"regional","registerEn":"regional","example":"A: 畑でかぼちゃを採ったよ。 B: いがいかぼちゃだね。","exampleEn":"A: I picked a pumpkin from the field. B: That’s a big pumpkin.","note":"「いがい」は大きいの意味。「意外」とは意味が異なる。","noteEn":"Igai means big in the Daigo dictionary, distinct from unexpected.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"棚のいりにあるよ","reading":"Tana no iri ni aru yo","standard":"棚の奥にあるよ","english":"It is at the back of the shelf.","scene":"家・探し物","sceneEn":"Home · looking for something","tag":"existence","register":"regional","registerEn":"regional","example":"A: 花瓶はどこ？ B: 棚のいりにあるよ。","exampleEn":"A: Where is the vase? B: It’s at the back of the shelf.","note":"「いり」は奥の意味。大子町の辞書の地域用法を紹介。","noteEn":"Iri means the back or inner part in this Daigo Town usage.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"竿のうらっぺを見て","reading":"Sao no urappe o mite","standard":"竿の先端を見て","english":"Look at the tip of the rod.","scene":"趣味・釣り道具","sceneEn":"Hobbies · fishing equipment","tag":"request","register":"regional","registerEn":"regional","example":"A: 糸をどこに通すの？ B: 竿のうらっぺを見て。","exampleEn":"A: Where does the line go? B: Look at the tip of the rod.","note":"「うらっぺ」は先端。大子町の辞書では釣り竿の例がある。","noteEn":"Urappe means tip; the Daigo dictionary gives a fishing-rod example.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"おごうこを少し食べる","reading":"Ogōko o sukoshi taberu","standard":"お新香を少し食べる","english":"Eat a little of the pickles.","scene":"食事・漬物","sceneEn":"Meals · pickles","tag":"food","register":"regional","registerEn":"regional","example":"A: おごうこもどうぞ。 B: 少しもらうね。","exampleEn":"A: Have some pickles too. B: I’ll have a little.","note":"「おごうこ」はお新香、漬物。大子町で採録されたことば。","noteEn":"Ogōko means Japanese pickles; recorded in Daigo Town.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"おしびょうで留める","reading":"Oshibyō de tomeru","standard":"画鋲で留める","english":"Fasten it with a thumbtack.","scene":"掲示・道具","sceneEn":"Noticeboard · tools","tag":"work","register":"regional","registerEn":"regional","example":"A: この紙を掲示したい。 B: おしびょうで留めよう。","exampleEn":"A: I want to display this sheet. B: Let’s fasten it with a thumbtack.","note":"「おしびょう」は画鋲。大子町の方言辞書に掲載された語。","noteEn":"Oshibyō means thumbtack; listed in the Daigo Town dialect dictionary.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"ibaraki","phrase":"おにむしを見つけた","reading":"Onimushi o mitsuketa","standard":"クワガタムシを見つけた","english":"I found a stag beetle.","scene":"自然・虫の観察","sceneEn":"Nature · observing insects","tag":"animal","register":"regional","registerEn":"regional","example":"A: 木に虫がいるよ。 B: おにむしを見つけたね。","exampleEn":"A: There’s an insect on the tree. B: We found a stag beetle.","note":"「おにむし」はクワガタムシ。大子町の辞書にある呼び名。","noteEn":"Onimushi means stag beetle; listed in the Daigo Town dictionary.","sourceUrl":"https://www.town.daigo.ibaraki.jp/page/page000175.html","sourceTitle":"大子町公式ホームページ「大子弁辞書（あ行）」"},{"region":"fukui","phrase":"今日は人があまりえんね","reading":"Kyō wa hito ga amari en ne","standard":"今日は人があまりいないね","english":"There aren’t many people today.","scene":"店・混雑","sceneEn":"Shops · crowds","tag":"existence","register":"regional","registerEn":"regional","example":"A: 席を選べるね。 B: 今日は人があまりえんね。","exampleEn":"A: We can choose a seat. B: There aren’t many people today.","note":"「えん」はいないの意味。県の方言サイトでは嶺北の用例。","noteEn":"En means not present; the prefectural site lists it in the Reihoku section.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"fukui","phrase":"しなーっと練習していた","reading":"Shinātto renshū shite ita","standard":"こっそり練習していた","english":"I had been practicing in secret.","scene":"趣味・練習","sceneEn":"Hobbies · practice","tag":"progress","register":"regional","registerEn":"regional","example":"A: ピアノが上手になったね。 B: しなーっと練習していたよ。","exampleEn":"A: You’ve improved at piano. B: I had been practicing in secret.","note":"「しなーっと」はこっそりと。嶺北の会話例で紹介される。","noteEn":"Shinātto means secretly; illustrated in the site’s Reihoku dialogues.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"fukui","phrase":"この展示はおもっしぇーね","reading":"Kono tenji wa omosshē ne","standard":"この展示はおもしろいね","english":"This exhibit is interesting.","scene":"観光・展示","sceneEn":"Sightseeing · exhibits","tag":"reaction","register":"regional","registerEn":"regional","example":"A: 昔の道具が並んでいるよ。 B: この展示はおもっしぇーね。","exampleEn":"A: They have old tools on display. B: This exhibit is interesting.","note":"「おもっしぇー」はおもしろい。嶺北の会話例にある語。","noteEn":"Omosshē means interesting; listed in the Reihoku dialogue section.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"fukui","phrase":"はよしねー","reading":"Hayo shinē","standard":"早くしなさい","english":"Hurry up.","scene":"出発・急ぐとき","sceneEn":"Departure · hurrying","tag":"instruction","register":"regional","registerEn":"regional","example":"A: 出発まであと一分だよ。 B: はよしねー。","exampleEn":"A: We leave in one minute. B: Hurry up.","note":"嶺北の「しねー」はしなさいの意味。急かす言い方になる。","noteEn":"In Reihoku, shinē means do it; this expression urges someone to hurry.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"fukui","phrase":"この道具はおぞいね","reading":"Kono dōgu wa ozoi ne","standard":"この道具は古くて役に立たないね","english":"This tool is worn out and no longer useful.","scene":"家・道具","sceneEn":"Home · tools","tag":"adjective","register":"regional","registerEn":"regional","example":"A: この道具はもう動かない。 B: ずいぶんおぞいね。","exampleEn":"A: This tool no longer works. B: It’s worn out and no longer useful.","note":"嶺北の「おぞい」は古くて役に立たないこと。嶺南と異義。","noteEn":"In Reihoku, ozoi means old and useless; its eastern Reinan meaning differs.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"fukui","phrase":"捨てるのはおとましいね","reading":"Suteru no wa otomashii ne","standard":"捨てるのはもったいないね","english":"It would be a waste to throw it away.","scene":"片づけ・再利用","sceneEn":"Tidying · reuse","tag":"feeling","register":"regional","registerEn":"regional","example":"A: まだ使える箱だね。 B: 捨てるのはおとましいね。","exampleEn":"A: This box is still usable. B: It would be a waste to throw it away.","note":"嶺北の「おとましい」はもったいない。嶺南東部では異義。","noteEn":"In Reihoku, otomashii means wasteful; eastern Reinan has a different meaning.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"歩いてほっこりした","reading":"Aruite hokkori shita","standard":"歩いて疲れた","english":"Walking tired me out.","scene":"散歩・休憩","sceneEn":"Walking · a break","tag":"condition","register":"regional","registerEn":"regional","example":"A: 今日はよく歩いたね。 B: ほっこりしたよ。","exampleEn":"A: We walked a lot today. B: I’m tired.","note":"嶺南の「ほっこりする」は疲れるの意味。癒やしとは別義。","noteEn":"In Reinan, hokkori suru means become tired, rather than feel cozy.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"祖父は家におるよ","reading":"Sofu wa ie ni oru yo","standard":"祖父は家にいるよ","english":"My grandfather is at home.","scene":"家族・所在","sceneEn":"Family · whereabouts","tag":"existence","register":"regional","registerEn":"regional","example":"A: おじいさんは出かけた？ B: 祖父は家におるよ。","exampleEn":"A: Has your grandfather gone out? B: He’s at home.","note":"「おる」はいるの意味。県の方言サイトでは嶺南の用例。","noteEn":"Oru means be present; the prefectural site illustrates it for Reinan.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"あんじょー準備できた","reading":"Anjō junbi dekita","standard":"うまい具合に準備できた","english":"The preparations went well.","scene":"行事・準備","sceneEn":"Events · preparation","tag":"progress","register":"regional","registerEn":"regional","example":"A: 明日の用意は終わった？ B: あんじょー準備できたよ。","exampleEn":"A: Are tomorrow’s preparations done? B: They went well.","note":"「あんじょー」はうまい具合に、ちゃんと。嶺南の会話例。","noteEn":"Anjō means well or properly; recorded in the Reinan dialogue section.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"なした寒い朝だね","reading":"Nashita samui asa da ne","standard":"なんて寒い朝だね","english":"What a cold morning.","scene":"天気・朝","sceneEn":"Weather · morning","tag":"emphasis","register":"regional","registerEn":"regional","example":"A: 窓に霜がついているよ。 B: なした寒い朝だね。","exampleEn":"A: There’s frost on the window. B: What a cold morning.","note":"嶺南の「なした」はなんて、なんと。北海道の質問とは別義。","noteEn":"In Reinan, nashita means how or what an; it differs from Hokkaido’s question.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"そろそろいぬね","reading":"Sorosoro inu ne","standard":"そろそろ帰るね","english":"I’ll head home soon.","scene":"訪問・別れ","sceneEn":"Visits · leaving","tag":"farewell","register":"regional","registerEn":"regional","example":"A: もう夕方になったね。 B: そろそろいぬね。","exampleEn":"A: It’s evening already. B: I’ll head home soon.","note":"「いぬ」は帰る、いなくなる。嶺南の会話例にある動詞。","noteEn":"Inu means leave or go home; documented in the Reinan dialogues.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"雨が続くと、かなんね","reading":"Ame ga tsuzuku to, kanan ne","standard":"雨が続くと、困るね","english":"It’s a nuisance when the rain keeps going.","scene":"天気・予定","sceneEn":"Weather · plans","tag":"feeling","register":"regional","registerEn":"regional","example":"A: また洗濯物が乾かない。 B: 雨が続くと、かなんね。","exampleEn":"A: The laundry won’t dry again. B: It’s a nuisance when the rain keeps going.","note":"「かなん」は困るの意味。県の方言サイトでは嶺南の用例。","noteEn":"Kanan means troublesome; the prefectural site documents it for Reinan.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"暗い道はおぞいね","reading":"Kurai michi wa ozoi ne","standard":"暗い道は恐ろしいね","english":"A dark road feels frightening.","scene":"夜・道","sceneEn":"Night · roads","tag":"feeling","register":"regional","registerEn":"regional","example":"A: この道は街灯が少ない。 B: 暗い道はおぞいね。","exampleEn":"A: This road has few streetlights. B: A dark road feels frightening.","note":"嶺南東部の「おぞい」は恐ろしい。嶺北の意味とは異なる。","noteEn":"In eastern Reinan, ozoi means frightening; its Reihoku meaning differs.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"reinan","phrase":"虫が飛び回って、おとましい","reading":"Mushi ga tobimawatte, otomashii","standard":"虫が飛び回って、わずらわしい","english":"The insects flying around are a nuisance.","scene":"庭・虫","sceneEn":"Garden · insects","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 顔の周りに虫が来るね。 B: 飛び回って、おとましい。","exampleEn":"A: Insects keep coming near our faces. B: They’re a nuisance flying around.","note":"嶺南東部の「おとましい」はうるさい、わずらわしいの意味。","noteEn":"In eastern Reinan, otomashii means noisy or bothersome.","sourceUrl":"https://fupo.jp/lp/fukuiben/","sourceTitle":"福井県制作「しあわせを呼ぶ福井の方言」（加藤和夫監修）"},{"region":"toyama","phrase":"つかえんよ","reading":"Tsukaen yo","standard":"かまわないよ／問題ないよ","english":"That’s fine; no problem.","scene":"頼みごと・返事","sceneEn":"Requests · replies","tag":"reassurance","register":"regional","registerEn":"regional","example":"A: 窓を開けてもいい？ B: つかえんよ。","exampleEn":"A: May I open the window? B: That’s fine.","note":"富山の「つかえん」はかまわない、問題ないの意味で使う。","noteEn":"Toyama tsukaen means no problem or that’s fine.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"やんばいに進んでいる","reading":"Yanbai ni susunde iru","standard":"いい具合に進んでいる","english":"It is progressing well.","scene":"仕事・進み具合","sceneEn":"Work · progress","tag":"progress","register":"regional","registerEn":"regional","example":"A: 作業はどう？ B: やんばいに進んでいるよ。","exampleEn":"A: How is the task going? B: It’s progressing well.","note":"「やんばい」はいい具合に、運よく。県の方言ガイドの語。","noteEn":"Yanbai means in good condition or luckily; listed in the prefectural guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"大きな音でいきそった","reading":"Ōkina oto de ikisotta","standard":"大きな音で驚いた","english":"The loud noise startled me.","scene":"日常・音","sceneEn":"Daily life · sounds","tag":"reaction","register":"regional","registerEn":"regional","example":"A: 突然ドアが閉まったね。 B: 大きな音でいきそった。","exampleEn":"A: The door suddenly shut. B: The loud noise startled me.","note":"「いきそる」は驚くの意味。富山県の方言ガイドで確認。","noteEn":"Ikisoru means be surprised; attested in the Toyama prefectural guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"うまくできなくて、はがやしい","reading":"Umaku dekinakute, hagayashii","standard":"うまくできなくて、悔しい","english":"It’s frustrating that I can’t get it right.","scene":"趣味・練習","sceneEn":"Hobbies · practice","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 編み目をまた間違えた。 B: うまくできなくて、はがやしいね。","exampleEn":"A: I got the stitches wrong again. B: It’s frustrating not getting it right.","note":"「はがやしい」は悔しい、腹が立つ気持ち。富山の記録語。","noteEn":"Hagayashii expresses frustration or anger; documented for Toyama.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"このスープはしょむないね","reading":"Kono sūpu wa shomunai ne","standard":"このスープは味が薄いね","english":"This soup tastes bland.","scene":"食事・味","sceneEn":"Meals · flavor","tag":"food","register":"regional","registerEn":"regional","example":"A: スープを作ったよ。 B: 少ししょむないね。","exampleEn":"A: I made soup. B: It tastes a little bland.","note":"「しょむない」は味が薄いの意味。富山県の食事語の例。","noteEn":"Shomunai means bland; included in Toyama’s meal vocabulary.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"この煮物はくどいね","reading":"Kono nimono wa kudoi ne","standard":"この煮物は味が濃いね","english":"This simmered dish is strongly seasoned.","scene":"食事・味付け","sceneEn":"Meals · seasoning","tag":"food","register":"regional","registerEn":"regional","example":"A: しょうゆを多く入れた？ B: この煮物はくどいね。","exampleEn":"A: Did you add a lot of soy sauce? B: This dish is strongly seasoned.","note":"食事での「くどい」は味が濃いの意味。県のガイドの用法。","noteEn":"In this meal context, kudoi means strongly seasoned; the guide records this use.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"このご飯はこわいね","reading":"Kono gohan wa kowai ne","standard":"このご飯はかたいね","english":"This rice is hard.","scene":"食事・食感","sceneEn":"Meals · texture","tag":"food","register":"regional","registerEn":"regional","example":"A: 炊き上がりはどう？ B: このご飯はこわいね。","exampleEn":"A: How did the rice turn out? B: It’s hard.","note":"食べ物の「こわい」はかたいの意味。怖さを述べる語とは別。","noteEn":"For food, kowai means hard; this differs from frightening.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"本がでかいとあるね","reading":"Hon ga dekaito aru ne","standard":"本がたくさんあるね","english":"There are lots of books.","scene":"図書館・数量","sceneEn":"Library · quantity","tag":"quantity","register":"regional","registerEn":"regional","example":"A: この部屋は読書室だよ。 B: 本がでかいとあるね。","exampleEn":"A: This is the reading room. B: There are lots of books.","note":"「でかいと」はたくさんの意味。大きさではなく量を表す。","noteEn":"Dekaito means a lot; it refers to quantity rather than size.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ご飯はちょっこでいい","reading":"Gohan wa chokko de ii","standard":"ご飯は少しでいい","english":"Just a little rice is enough.","scene":"食事・量","sceneEn":"Meals · portions","tag":"quantity","register":"regional","registerEn":"regional","example":"A: ご飯をよそうね。 B: ちょっこでいいよ。","exampleEn":"A: I’ll serve you rice. B: Just a little is enough.","note":"「ちょっこ」は少しの意味。富山県の食事場面の採録語。","noteEn":"Chokko means a little; attested in the Toyama guide’s meal section.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ていっしゅを出すね","reading":"Teisshu o dasu ne","standard":"小皿を出すね","english":"I’ll bring out small plates.","scene":"食事・配膳","sceneEn":"Meals · setting the table","tag":"food","register":"regional","registerEn":"regional","example":"A: 漬物を分けたいね。 B: ていっしゅを出すね。","exampleEn":"A: Let’s divide the pickles. B: I’ll bring out small plates.","note":"「ていっしゅ」は小皿。音の近いティッシュとは意味が違う。","noteEn":"Teisshu means small plate, distinct from the similar-sounding tissue.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ちりしを取ってくれる？","reading":"Chirishi o totte kureru?","standard":"ティッシュを取ってくれる？","english":"Could you pass me a tissue?","scene":"家・身の回り","sceneEn":"Home · everyday items","tag":"request","register":"regional","registerEn":"regional","example":"A: ちりしを取ってくれる？ B: 机の上の箱だね。","exampleEn":"A: Could you pass me a tissue? B: The box on the desk, right?","note":"「ちりし」はちり紙、ティッシュ。富山県ガイドの物の語。","noteEn":"Chirishi means tissue paper; listed in the Toyama guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ゆあげを用意したよ","reading":"Yuage o yōi shita yo","standard":"タオルを用意したよ","english":"I’ve prepared a towel.","scene":"風呂・持ち物","sceneEn":"Bath · belongings","tag":"daily","register":"regional","registerEn":"regional","example":"A: お風呂に入るね。 B: ゆあげを用意したよ。","exampleEn":"A: I’m going to take a bath. B: I’ve prepared a towel.","note":"「ゆあげ」は湯上がりに使うタオル。県の方言ガイドの語。","noteEn":"Yuage means a towel, especially after bathing; attested in the guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ぎりぎりはここだよ","reading":"Girigiri wa koko da yo","standard":"つむじはここだよ","english":"The hair whorl is here.","scene":"身支度・髪","sceneEn":"Getting ready · hair","tag":"body","register":"regional","registerEn":"regional","example":"A: 髪が立つのはどこ？ B: ぎりぎりはここだよ。","exampleEn":"A: Where does the hair stick up? B: The hair whorl is here.","note":"身体の「ぎりぎり」はつむじ。限度を表す共通語とは別義。","noteEn":"As body vocabulary, girigiri means hair whorl, not just at the limit.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"けべすの部分を見て","reading":"Kebesu no bubun o mite","standard":"かかとの部分を見て","english":"Look at the heel area.","scene":"買い物・靴","sceneEn":"Shopping · shoes","tag":"body","register":"regional","registerEn":"regional","example":"A: 靴のどこが減っている？ B: けべすの部分を見て。","exampleEn":"A: Which part of the shoe is worn down? B: Look at the heel area.","note":"「けべす」はかかとのこと。富山県の身体語のガイドに掲載。","noteEn":"Kebesu means heel; listed among body words in the Toyama guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ありがたーなってきた","reading":"Arigatā natte kita","standard":"眠くなってきた","english":"I’m getting sleepy.","scene":"夜・くつろぎ","sceneEn":"Evening · relaxing","tag":"condition","register":"regional","registerEn":"regional","example":"A: 映画の続きを見る？ B: ありがたーなってきたよ。","exampleEn":"A: Shall we watch the rest of the film? B: I’m getting sleepy.","note":"「ありがたーなる」は眠くなるの意味。お礼の表現ではない。","noteEn":"Arigatā naru means become sleepy, rather than express gratitude.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"少しなごなるね","reading":"Sukoshi nagonaru ne","standard":"少し横になるね","english":"I’ll lie down for a bit.","scene":"家・休憩","sceneEn":"Home · resting","tag":"break","register":"regional","registerEn":"regional","example":"A: ソファーが空いているよ。 B: 少しなごなるね。","exampleEn":"A: The sofa is free. B: I’ll lie down for a bit.","note":"「なごなる」は寝る、横になる。富山県の動作語の記録。","noteEn":"Nagonaru means sleep or lie down; recorded in the Toyama guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ひらすまをする","reading":"Hirasuma o suru","standard":"昼寝をする","english":"Take an afternoon nap.","scene":"休日・休憩","sceneEn":"Day off · rest","tag":"break","register":"regional","registerEn":"regional","example":"A: 午後は何をする？ B: 少しひらすまをするよ。","exampleEn":"A: What will you do this afternoon? B: I’ll take a short nap.","note":"「ひらすま」は昼寝。富山県の方言ガイドの動作語にある。","noteEn":"Hirasuma means an afternoon nap; attested in Toyama’s guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"ここにねまるね","reading":"Koko ni nemaru ne","standard":"ここに座るね","english":"I’ll sit here.","scene":"訪問・席","sceneEn":"Visits · seating","tag":"action","register":"regional","registerEn":"regional","example":"A: こちらの席が空いているよ。 B: ここにねまるね。","exampleEn":"A: This seat is free. B: I’ll sit here.","note":"「ねまる」は座るの意味。寝るとは意味が違うので文脈で聞く。","noteEn":"Nemaru means sit down, distinct from sleeping; use the context.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"本をまたいするね","reading":"Hon o matai suru ne","standard":"本を片づけるね","english":"I’ll put the books away.","scene":"家事・片づけ","sceneEn":"Housework · tidying","tag":"cleanup","register":"regional","registerEn":"regional","example":"A: 机を使ってもいい？ B: 本をまたいするね。","exampleEn":"A: May I use the desk? B: I’ll put the books away.","note":"「またいする」は片づける、保存する。富山県ガイドの語。","noteEn":"Matai suru means put away or store; listed in the Toyama guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"toyama","phrase":"切符をうしなかした","reading":"Kippu o ushinakashita","standard":"切符をなくした","english":"I lost my ticket.","scene":"移動・忘れ物","sceneEn":"Travel · lost items","tag":"status","register":"regional","registerEn":"regional","example":"A: 改札に行こう。 B: 切符をうしなかした。","exampleEn":"A: Let’s go to the ticket gate. B: I lost my ticket.","note":"「うしなかす」は紛失する、なくす。富山県の動作語の記録。","noteEn":"Ushinakasu means lose or misplace; documented in the Toyama guide.","sourceUrl":"https://www.pref.toyama.jp/documents/18558/manual-design_0315low.pdf","sourceTitle":"富山県厚生部「とやま方言マニュアル」（中井精一監修、2022年3月）"},{"region":"tsugaru","phrase":"きみを焼こう","reading":"Kimi o yakō","standard":"とうもろこしを焼こう","english":"Let’s grill some corn.","scene":"食事・夏の野菜","sceneEn":"Meals · summer vegetables","tag":"food","register":"regional","registerEn":"regional","example":"A: きみを買ってきたよ。 B: 夕飯に焼こう。","exampleEn":"A: I bought some corn. B: Let’s grill it for dinner.","note":"津軽の「きみ」はとうもろこし。弘前市の紹介ページで確認。","noteEn":"Tsugaru kimi means corn; explicitly defined by Hirosaki City.","sourceUrl":"https://www.city.hirosaki.aomori.jp/city_promotion/topics/2024/08/20240816.html","sourceTitle":"弘前市「嶽きみのシーズンが到来しました！」"},{"region":"tsugaru","phrase":"私は少しじょっぱりだね","reading":"Watashi wa sukoshi joppari da ne","standard":"私は少し意地っ張りだね","english":"I’m a little stubborn.","scene":"会話・自己紹介","sceneEn":"Conversation · self-description","tag":"personality","register":"regional","registerEn":"regional","example":"A: 最後まで自分でやりたいの？ B: うん、私は少しじょっぱりだね。","exampleEn":"A: Do you want to finish it yourself? B: Yes; I’m a little stubborn.","note":"「じょっぱり」は意地っ張り、頑固者。人への評価にもなる。","noteEn":"Joppari means stubborn person; it can carry a judgment about someone.","sourceUrl":"https://www.pref.aomori.lg.jp/soshiki/soumu/zeimu/files/aomorifurusatokifukin2021_2.pdf","sourceTitle":"青森県ふるさと寄附金返礼品案内2021「じょっぱり」解説"},{"region":"tsugaru","phrase":"なとわで写真を撮ろう","reading":"Natowa de shashin o torō","standard":"あなたと私で写真を撮ろう","english":"Let’s take a photo of you and me.","scene":"旅行・記念写真","sceneEn":"Travel · souvenir photo","tag":"invitation","register":"regional","registerEn":"regional","example":"A: ここで記念に一枚どう？ B: なとわで写真を撮ろう。","exampleEn":"A: How about a souvenir photo here? B: Let’s take a photo of you and me.","note":"津軽の「なとわ」はあなたと私。県の公式商品解説で確認。","noteEn":"Tsugaru natowa means you and I; explicitly defined in a prefectural page.","sourceUrl":"https://oshimiyage.pref.aomori.lg.jp/entry-list/?department=%E3%82%BD%E3%83%95%E3%83%88%E3%83%89%E3%83%AA%E3%83%B3%E3%82%AF","sourceTitle":"青森県「青の煌めきあおもり推し土産総選挙2026」なとわ解説"},{"region":"tsugaru","phrase":"さんじゃらっと待って","reading":"Sanjaratto matte","standard":"ちょっと待って","english":"Wait a little.","scene":"待ち合わせ・準備","sceneEn":"Meeting up · preparation","tag":"request","register":"regional","registerEn":"regional","example":"A: もう出発する？ B: さんじゃらっと待って。靴を履くね。","exampleEn":"A: Are we leaving now? B: Wait a little; I’ll put on my shoes.","note":"「さんじゃらっと」は少し、ちょっと。青森県の報告書の語。","noteEn":"Sanjaratto means a little; explicitly defined in an Aomori prefectural report.","sourceUrl":"https://www.pref.aomori.lg.jp/soshiki/kodomo/wakamono/files/2010-0318-1541.pdf","sourceTitle":"青森県地域社会報告書「サン・じゃらっと」語義解説"},{"region":"niigata","phrase":"しゃっこい","reading":"Shakkoi","standard":"冷たい","english":"cold","scene":"飲み物","sceneEn":"Drinks","tag":"adjective","register":"regional","registerEn":"regional","example":"A: この水、しゃっこいね。 B: 冷蔵庫に入れておいたよ。","exampleEn":"A: This water is cold. B: I kept it in the fridge.","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"niigata","phrase":"じょんのび","reading":"Jonnobi","standard":"ゆったり、のんびり","english":"relaxing; taking it easy","scene":"休日","sceneEn":"Days off","tag":"break","register":"regional","registerEn":"regional","example":"A: 午後はじょんのび過ごそう。 B: 本でも読もうか。","exampleEn":"A: Let’s take it easy this afternoon. B: Shall we read?","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"niigata","phrase":"腹くっちぇー","reading":"Hara kutchē","standard":"お腹がいっぱい","english":"I’m full","scene":"食後","sceneEn":"After a meal","tag":"food","register":"regional","registerEn":"regional","example":"A: 腹くっちぇー。 B: デザートは後にしよう。","exampleEn":"A: I’m full. B: Let’s save dessert for later.","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"niigata","phrase":"きんな","reading":"Kinna","standard":"昨日","english":"yesterday","scene":"予定の確認","sceneEn":"Checking plans","tag":"daily","register":"regional","registerEn":"regional","example":"A: きんな、図書館に行った？ B: うん、本を借りた。","exampleEn":"A: Did you go to the library yesterday? B: Yes, I borrowed a book.","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"niigata","phrase":"べと","reading":"Beto","standard":"土","english":"soil","scene":"園芸","sceneEn":"Gardening","tag":"daily","register":"regional","registerEn":"regional","example":"A: 鉢にべとを入れて。 B: この袋の土でいい？","exampleEn":"A: Put soil in the pot. B: Is the soil in this bag okay?","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"niigata","phrase":"ねまる","reading":"Nemaru","standard":"座る","english":"sit down","scene":"待ち合わせ","sceneEn":"Meeting up","tag":"action","register":"regional","registerEn":"regional","example":"A: ここにねまろう。 B: バスまで少し時間があるね。","exampleEn":"A: Let’s sit here. B: We have time before the bus.","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"niigata","phrase":"ごっつぉ","reading":"Gottsuo","standard":"ごちそう","english":"feast; special meal","scene":"食事","sceneEn":"Meals","tag":"food","register":"regional","registerEn":"regional","example":"A: 今日はごっつぉだね。 B: みんなで作ったんだ。","exampleEn":"A: What a feast today. B: We all made it together.","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"niigata","phrase":"やっこい","reading":"Yakkoi","standard":"柔らかい","english":"soft","scene":"食感","sceneEn":"Food texture","tag":"adjective","register":"regional","registerEn":"regional","example":"A: このパン、やっこいね。 B: 焼きたてだよ。","exampleEn":"A: This bread is soft. B: It’s freshly baked.","note":"県内辞典の掲載語。地域差に注意。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://niigata-kankou.or.jp/location/dialect-dictionary/","sourceTitle":"新潟県フィルムコミッション：方言辞典"},{"region":"kofu","phrase":"ぼこ","reading":"Boko","standard":"子ども","english":"child","scene":"家族","sceneEn":"Family","tag":"daily","register":"regional","registerEn":"regional","example":"A: 写真に写っているのは？ B: 近所のぼこだよ。","exampleEn":"A: Who is in the photo? B: A child from the neighborhood.","note":"「ぼこ」は子どものこと。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"kofu","phrase":"くむ","reading":"Kumu","standard":"交換する","english":"exchange; swap","scene":"持ち物","sceneEn":"Belongings","tag":"action","register":"regional","registerEn":"regional","example":"A: このカード、くんでもいい？ B: うん、交換しよう。","exampleEn":"A: Can we swap these cards? B: Sure, let’s exchange them.","note":"「くむ」は交換する意味でも使う。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"kofu","phrase":"ぶちゃる","reading":"Bucharu","standard":"捨てる","english":"throw away","scene":"片づけ","sceneEn":"Tidying up","tag":"cleanup","register":"regional","registerEn":"regional","example":"A: この古い袋、ぶちゃっていい？ B: うん、もう使わないよ。","exampleEn":"A: Can I throw away this old bag? B: Yes, we don’t use it.","note":"「ぶちゃる」は物を捨てること。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"kofu","phrase":"かじる","reading":"Kajiru","standard":"皮膚をかく","english":"scratch the skin","scene":"体の表現","sceneEn":"Body vocabulary","tag":"body","register":"regional","registerEn":"regional","example":"A: 背中をかじるって？ B: 背中をかく、という意味だよ。","exampleEn":"A: What does “kajiru one’s back” mean? B: Scratch one’s back.","note":"この用法の「かじる」は、かくこと。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"kofu","phrase":"持ちに行く","reading":"Mochi ni iku","standard":"取りに行く","english":"go and fetch","scene":"忘れ物","sceneEn":"Forgotten items","tag":"action","register":"regional","registerEn":"regional","example":"A: 傘を持ちに行くね。 B: 入口で待っているよ。","exampleEn":"A: I’ll go fetch my umbrella. B: I’ll wait at the entrance.","note":"受け取りに行く意味の表現。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"kofu","phrase":"ぬくとい","reading":"Nukutoi","standard":"温かい","english":"warm","scene":"冬の日常","sceneEn":"Winter daily life","tag":"adjective","register":"regional","registerEn":"regional","example":"A: この毛布、ぬくといね。 B: もう一枚あるよ。","exampleEn":"A: This blanket is warm. B: There’s another one.","note":"温かさを表すことば。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"kofu","phrase":"いくじ","reading":"Ikuji","standard":"いつ、何時","english":"when; what time","scene":"予定","sceneEn":"Plans","tag":"question","register":"regional","registerEn":"regional","example":"A: 集合はいくじ？ B: 午前九時だよ。","exampleEn":"A: What time do we meet? B: Nine in the morning.","note":"時刻や時を尋ねる語。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"kofu","phrase":"いっさら","reading":"Issara","standard":"少しも、全く（否定とともに）","english":"not at all","scene":"進み具合","sceneEn":"Progress","tag":"negative","register":"regional","registerEn":"regional","example":"A: 今日は風がいっさらないね。 B: 旗も動いていない。","exampleEn":"A: There’s no wind at all today. B: The flag isn’t moving either.","note":"否定表現と合わせて使う語。","noteEn":"Kofu survey records this local meaning.","sourceUrl":"https://www.city.kofu.yamanashi.jp/shise/koho/koshuben.html","sourceTitle":"甲府市：直撃！甲州弁アンケート"},{"region":"yamanashi","phrase":"ももっちい","reading":"Momotchii","standard":"くすぐったい","english":"ticklish","scene":"感覚","sceneEn":"Sensations","tag":"body","register":"local","registerEn":"traditional / local","example":"A: 羽が手に触れるとももっちい。 B: ふわふわしているね。","exampleEn":"A: The feather feels ticklish on my hand. B: It’s fluffy.","note":"県の番付表に記録された語。地域・世代差あり。","noteEn":"Documented traditional word; usage varies.","sourceUrl":"https://www.pref.yamanashi.jp/documents/27878/hougen.pdf","sourceTitle":"山梨県：甲州方言（なまり）番付表"},{"region":"yamanashi","phrase":"ひどろい","reading":"Hidoroi","standard":"まぶしい","english":"dazzling; bright","scene":"日差し","sceneEn":"Sunlight","tag":"adjective","register":"local","registerEn":"traditional / local","example":"A: 西日がひどろいね。 B: カーテンを閉めよう。","exampleEn":"A: The evening sun is dazzling. B: Let’s close the curtain.","note":"県の番付表に記録された語。地域・世代差あり。","noteEn":"Documented traditional word; usage varies.","sourceUrl":"https://www.pref.yamanashi.jp/documents/27878/hougen.pdf","sourceTitle":"山梨県：甲州方言（なまり）番付表"},{"region":"yamanashi","phrase":"ばんてに","reading":"Bante ni","standard":"かわるがわる","english":"in turns","scene":"共同作業","sceneEn":"Working together","tag":"action","register":"local","registerEn":"traditional / local","example":"A: ばんてに荷物を運ぼう。 B: 次は私が持つね。","exampleEn":"A: Let’s carry the luggage in turns. B: I’ll take the next turn.","note":"県の番付表に記録された語。地域・世代差あり。","noteEn":"Documented traditional word; usage varies.","sourceUrl":"https://www.pref.yamanashi.jp/documents/27878/hougen.pdf","sourceTitle":"山梨県：甲州方言（なまり）番付表"},{"region":"yamanashi","phrase":"きびしょ","reading":"Kibisho","standard":"急須","english":"teapot","scene":"お茶","sceneEn":"Tea","tag":"daily","register":"local","registerEn":"traditional / local","example":"A: きびしょはどこ？ B: 棚の上にあるよ。","exampleEn":"A: Where is the teapot? B: On the shelf.","note":"県の番付表に記録された語。地域・世代差あり。","noteEn":"Documented traditional word; usage varies.","sourceUrl":"https://www.pref.yamanashi.jp/documents/27878/hougen.pdf","sourceTitle":"山梨県：甲州方言（なまり）番付表"},{"region":"yamanashi","phrase":"けんごうず","reading":"Kengōzu","standard":"米のとぎ汁","english":"rice rinsing water","scene":"台所","sceneEn":"Kitchen","tag":"food","register":"local","registerEn":"traditional / local","example":"A: この白い水は何？ B: けんごうずだよ。","exampleEn":"A: What is this cloudy water? B: Rice rinsing water.","note":"県の番付表に記録された語。地域・世代差あり。","noteEn":"Documented traditional word; usage varies.","sourceUrl":"https://www.pref.yamanashi.jp/documents/27878/hougen.pdf","sourceTitle":"山梨県：甲州方言（なまり）番付表"},{"region":"yamanashi","phrase":"ありんどう","reading":"Arindō","standard":"蟻","english":"ant","scene":"庭","sceneEn":"Garden","tag":"animal","register":"local","registerEn":"traditional / local","example":"A: ありんどうが歩いているね。 B: 花壇の方へ行った。","exampleEn":"A: An ant is walking here. B: It went toward the flower bed.","note":"県の番付表に記録された語。地域・世代差あり。","noteEn":"Documented traditional word; usage varies.","sourceUrl":"https://www.pref.yamanashi.jp/documents/27878/hougen.pdf","sourceTitle":"山梨県：甲州方言（なまり）番付表"},{"region":"gifu-city","phrase":"あっちべた","reading":"Acchibeta","standard":"向こう側、あちらの方","english":"over there; the other side","scene":"道案内","sceneEn":"Directions","tag":"daily","register":"regional","registerEn":"regional","example":"A: お店はどこ？ B: 川のあっちべただよ。","exampleEn":"A: Where’s the shop? B: On the other side of the river.","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"いざける","reading":"Izakeru","standard":"移動させる","english":"move something","scene":"片づけ","sceneEn":"Tidying up","tag":"action","register":"regional","registerEn":"regional","example":"A: 箱を少しいざけて。 B: 窓の下でいい？","exampleEn":"A: Move the box a little. B: Is under the window okay?","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"いのく","reading":"Inoku","standard":"動く","english":"move","scene":"機械","sceneEn":"Machines","tag":"action","register":"regional","registerEn":"regional","example":"A: このおもちゃ、いのく？ B: 電池を入れると動くよ。","exampleEn":"A: Does this toy move? B: It moves with batteries.","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"がばり","reading":"Gabari","standard":"画鋲","english":"thumbtack","scene":"掲示","sceneEn":"Putting up notices","tag":"daily","register":"regional","registerEn":"regional","example":"A: がばりを一本取って。 B: この箱にあるよ。","exampleEn":"A: Pass me a thumbtack. B: They’re in this box.","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"かしわ","reading":"Kashiwa","standard":"鶏肉","english":"chicken meat","scene":"買い物","sceneEn":"Shopping","tag":"food","register":"regional","registerEn":"regional","example":"A: 今日はかしわを買おう。 B: 何を作るの？","exampleEn":"A: Let’s buy chicken today. B: What are we making?","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"きもい","reading":"Kimoi","standard":"きつい、窮屈だ","english":"tight; cramped","scene":"衣服","sceneEn":"Clothes","tag":"adjective","register":"regional","registerEn":"regional","example":"A: この靴、きもいね。 B: 大きいサイズを試そう。","exampleEn":"A: These shoes feel tight. B: Let’s try a larger size.","note":"この方言用法では衣服などが窮屈なこと。","noteEn":"Here it means tight or cramped.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"けなるい","reading":"Kenarui","standard":"うらやましい","english":"envious","scene":"旅行の話","sceneEn":"Travel conversation","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 海の見える部屋に泊まったよ。 B: けなるいなあ。","exampleEn":"A: I stayed in a room with an ocean view. B: I’m envious.","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"ざいしょ","reading":"Zaisho","standard":"実家、出身地、ふるさと","english":"family home; hometown","scene":"帰省","sceneEn":"Going home","tag":"daily","register":"regional","registerEn":"regional","example":"A: 休みはどうする？ B: ざいしょに帰るよ。","exampleEn":"A: What will you do over the break? B: Go to my family home.","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"くろ","reading":"Kuro","standard":"片側、隅","english":"edge; corner","scene":"掃除","sceneEn":"Cleaning","tag":"cleanup","register":"regional","registerEn":"regional","example":"A: 部屋のくろにも紙がある。 B: 一緒に片づけよう。","exampleEn":"A: There’s paper in the corner too. B: Let’s tidy up together.","note":"市の方言資料に掲載。地域・世代差あり。","noteEn":"Listed by Gifu city; usage varies.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"gifu-city","phrase":"おきんさい","reading":"Okinsai","standard":"やめなさい","english":"stop that","scene":"注意","sceneEn":"Giving a warning","tag":"warning","register":"regional","registerEn":"regional","example":"A: おきんさい。 B: わかった、静かにするよ。","exampleEn":"A: Stop that. B: Okay, I’ll be quiet.","note":"行為を止める表現。目上には避ける。","noteEn":"A directive to stop; avoid with superiors.","sourceUrl":"https://www.city.gifu.lg.jp/_res/projects/default_project/_page_/001/005/148/r6shiryouhenn.pdf","sourceTitle":"岐阜市：まちなか博士認定試験テキスト・資料編「岐阜の方言」"},{"region":"hida","phrase":"おねる","reading":"Oneru","standard":"背負う","english":"carry on one’s back","scene":"通学","sceneEn":"Going to school","tag":"action","register":"regional","registerEn":"regional","example":"A: ランドセルをおねった？ B: うん、準備できた。","exampleEn":"A: Have you put on your school backpack? B: Yes, I’m ready.","note":"高山市の聞き取り記事に掲載。","noteEn":"Recorded in a Takayama city interview.","sourceUrl":"https://www.city.takayama.lg.jp/shisei/1015214/1021586/1021628.html","sourceTitle":"高山市：海の街から山の街にやってきた4児のママに聞いてみた"},{"region":"hida","phrase":"ちゃんちん","reading":"Chanchin","standard":"座る（幼児へのことば）","english":"sit down (to a small child)","scene":"子どもとの会話","sceneEn":"Talking to a small child","tag":"instruction","register":"regional","registerEn":"regional","example":"A: ここでちゃんちんしようね。 B: 椅子を持ってくるね。","exampleEn":"A: Let’s sit here, little one. B: I’ll bring a chair.","note":"幼児に向けて使う座ることば。","noteEn":"A word for sitting, addressed to toddlers.","sourceUrl":"https://www.city.takayama.lg.jp/shisei/1015214/1021586/1021628.html","sourceTitle":"高山市：海の街から山の街にやってきた4児のママに聞いてみた"},{"region":"hida","phrase":"あおにえ","reading":"Aonie","standard":"青あざ","english":"bruise","scene":"体の表現","sceneEn":"Body vocabulary","tag":"body","register":"regional","registerEn":"regional","example":"A: あおにえって何？ B: 青あざのことだよ。","exampleEn":"A: What does “aonie” mean? B: A bruise.","note":"高山市の聞き取り記事に掲載。","noteEn":"Recorded in a Takayama city interview.","sourceUrl":"https://www.city.takayama.lg.jp/shisei/1015214/1021586/1021628.html","sourceTitle":"高山市：海の街から山の街にやってきた4児のママに聞いてみた"},{"region":"hida","phrase":"はんちくたい","reading":"Hanchikutai","standard":"むかつく、腹が立つ","english":"irritating; annoying","scene":"気持ち","sceneEn":"Feelings","tag":"feeling","register":"regional","registerEn":"regional","example":"A: また順番を抜かされた。はんちくたいなあ。 B: 受付で確認しよう。","exampleEn":"A: Someone jumped the queue again. That’s annoying. B: Let’s ask at reception.","note":"腹立たしい気持ちの表現。","noteEn":"Expresses irritation.","sourceUrl":"https://www.city.takayama.lg.jp/shisei/1015214/1021586/1021628.html","sourceTitle":"高山市：海の街から山の街にやってきた4児のママに聞いてみた"},{"region":"hida","phrase":"ささって","reading":"Sasatte","standard":"今日から三日後（明後日の翌日）","english":"three days from today","scene":"日程","sceneEn":"Schedules","tag":"daily","register":"regional","registerEn":"regional","example":"A: ささって会おう。 B: 念のため日付も教えて。","exampleEn":"A: Let’s meet three days from today. B: Tell me the date too.","note":"飛騨では「あさって」の次の日。日付も確認。","noteEn":"In Hida, the day after asatte; confirm the date.","sourceUrl":"https://www.city.takayama.lg.jp/shisei/1015214/1021586/1021628.html","sourceTitle":"高山市：海の街から山の街にやってきた4児のママに聞いてみた"},{"region":"hida","phrase":"机をつる","reading":"Tsukue o tsuru","standard":"机を運ぶ","english":"carry a desk","scene":"教室","sceneEn":"Classroom","tag":"action","register":"regional","registerEn":"regional","example":"A: 机をつるのを手伝って。 B: 二人で運ぼう。","exampleEn":"A: Help me carry the desk. B: Let’s carry it together.","note":"高山市の聞き取り記事に掲載。","noteEn":"Recorded in a Takayama city interview.","sourceUrl":"https://www.city.takayama.lg.jp/shisei/1015214/1021586/1021628.html","sourceTitle":"高山市：海の街から山の街にやってきた4児のママに聞いてみた"},{"region":"hida","phrase":"きっつい","reading":"Kittsui","standard":"元気だ、強い（人について）","english":"energetic; strong","scene":"会話の理解","sceneEn":"Understanding conversation","tag":"compliment","register":"regional","registerEn":"regional","example":"A: あの人、きっついね。 B: 元気という意味で言っているんだね。","exampleEn":"A: That person is energetic. B: You mean full of energy.","note":"ここでは人の元気さや強さを表す。","noteEn":"Here it praises someone’s vigor or strength.","sourceUrl":"https://www.city.takayama.lg.jp/shisei/1015214/1021586/1021628.html","sourceTitle":"高山市：海の街から山の街にやってきた4児のママに聞いてみた"},{"region":"hida","phrase":"ぼー","reading":"Bō","standard":"男の子","english":"boy","scene":"地域のことば","sceneEn":"Local vocabulary","tag":"daily","register":"regional","registerEn":"regional","example":"A: 「ぼー」って誰のこと？ B: 男の子のことだよ。","exampleEn":"A: Who does “bō” refer to? B: A boy.","note":"博物館が紹介する飛騨の子どもの呼び名。","noteEn":"A Hida child term documented by the museum.","sourceUrl":"https://www.city.takayama.lg.jp/machihaku/1005304/1008962.html","sourceTitle":"飛騨高山まちの博物館：平成27年度特別展「ぼーとびー」"},{"region":"hida","phrase":"びー","reading":"Bī","standard":"女の子","english":"girl","scene":"地域のことば","sceneEn":"Local vocabulary","tag":"daily","register":"regional","registerEn":"regional","example":"A: 展示名の「びー」って？ B: 女の子という意味だよ。","exampleEn":"A: What does “bī” in the exhibition title mean? B: Girl.","note":"博物館が紹介する飛騨の子どもの呼び名。","noteEn":"A Hida child term documented by the museum.","sourceUrl":"https://www.city.takayama.lg.jp/machihaku/1005304/1008962.html","sourceTitle":"飛騨高山まちの博物館：平成27年度特別展「ぼーとびー」"},{"region":"hida","phrase":"あぶらえ","reading":"Aburae","standard":"えごま","english":"egoma; perilla seed","scene":"地元の食材","sceneEn":"Local ingredients","tag":"food","register":"regional","registerEn":"regional","example":"A: あぶらえを売っているね。 B: えごまのことだよ。","exampleEn":"A: They’re selling aburae. B: That means egoma.","note":"飛騨での、えごまの呼び名。","noteEn":"The Hida name for egoma.","sourceUrl":"https://www.city.takayama.lg.jp/_res/projects/default_project/_page_/001/008/464/aburae.pdf","sourceTitle":"高山市地産地消推進会議：飛騨の旬の食材「あぶらえ」"},{"region":"kyoto","phrase":"あがる","reading":"Agaru","standard":"南北の通りを北へ行く","english":"go north along a street","scene":"道案内","sceneEn":"Directions","tag":"action","register":"regional","registerEn":"regional","example":"A: 烏丸通をあがるの？ B: うん、北へ進んで。","exampleEn":"A: Do we go north on Karasuma Street? B: Yes, head north.","note":"道案内では北へ進むこと。上の階ではない。","noteEn":"In street directions, it means going north.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"kyoto","phrase":"さがる","reading":"Sagaru","standard":"南北の通りを南へ行く","english":"go south along a street","scene":"道案内","sceneEn":"Directions","tag":"action","register":"regional","registerEn":"regional","example":"A: 寺町通をさがればいい？ B: うん、南の交差点まで。","exampleEn":"A: Should I go south on Teramachi Street? B: Yes, to the southern intersection.","note":"道案内では南へ進むこと。","noteEn":"In street directions, it means going south.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"kyoto","phrase":"ねき","reading":"Neki","standard":"そば、近く","english":"beside; nearby","scene":"待ち合わせ","sceneEn":"Meeting up","tag":"daily","register":"regional","registerEn":"regional","example":"A: 私は入口のねきにいるよ。 B: 今そちらへ行く。","exampleEn":"A: I’m near the entrance. B: I’m coming now.","note":"京都市の京ことば辞典に掲載。","noteEn":"Listed in Kyoto city’s local glossary.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"kyoto","phrase":"ぶぶ","reading":"Bubu","standard":"お茶","english":"tea","scene":"飲み物","sceneEn":"Drinks","tag":"food","register":"regional","registerEn":"regional","example":"A: ぶぶを入れようか。 B: ありがとう。","exampleEn":"A: Shall I make some tea? B: Thank you.","note":"京都市の京ことば辞典に掲載。","noteEn":"Listed in Kyoto city’s local glossary.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"kyoto","phrase":"でぼちん","reading":"Debochin","standard":"おでこ","english":"forehead","scene":"体の表現","sceneEn":"Body vocabulary","tag":"body","register":"regional","registerEn":"regional","example":"A: でぼちんってどこ？ B: おでこのことだよ。","exampleEn":"A: Where is “debochin”? B: Your forehead.","note":"京都市の京ことば辞典に掲載。","noteEn":"Listed in Kyoto city’s local glossary.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"kyoto","phrase":"きばる","reading":"Kibaru","standard":"がんばる","english":"make an effort","scene":"勉強","sceneEn":"Study","tag":"effort","register":"regional","registerEn":"regional","example":"A: あと一問、きばろう。 B: 一緒に考えよう。","exampleEn":"A: Let’s work on one more question. B: Let’s think together.","note":"京都市の京ことば辞典に掲載。","noteEn":"Listed in Kyoto city’s local glossary.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"kyoto","phrase":"そーろと","reading":"Sōroto","standard":"ゆっくりと","english":"slowly; gently","scene":"歩く","sceneEn":"Walking","tag":"care","register":"regional","registerEn":"regional","example":"A: そーろと歩こう。 B: 景色を見ながら行こう。","exampleEn":"A: Let’s walk slowly. B: Let’s enjoy the scenery.","note":"京都市の京ことば辞典に掲載。","noteEn":"Listed in Kyoto city’s local glossary.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"kyoto","phrase":"かんにん","reading":"Kannin","standard":"ごめん","english":"sorry; forgive me","scene":"謝る","sceneEn":"Apologizing","tag":"reaction","register":"regional","registerEn":"regional","example":"A: 待たせて、かんにん。 B: 大丈夫、今来たところ。","exampleEn":"A: Sorry to keep you waiting. B: It’s fine, I just arrived.","note":"京都市の京ことば辞典に掲載。","noteEn":"Listed in Kyoto city’s local glossary.","sourceUrl":"https://www.city.kyoto.lg.jp/sogo/page/0000097418.html","sourceTitle":"京都市：きょうとこども情報館・京ことば辞典"},{"region":"tango","phrase":"いらう","reading":"Irau","standard":"いじる、さわる","english":"touch; fiddle with","scene":"道具","sceneEn":"Tools","tag":"action","register":"regional","registerEn":"regional","example":"A: このつまみ、いらってもいい？ B: うん、音量の調節だよ。","exampleEn":"A: Can I touch this knob? B: Yes, it adjusts the volume.","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"tango","phrase":"めげる","reading":"Megeru","standard":"壊れる","english":"break; become damaged","scene":"持ち物","sceneEn":"Belongings","tag":"condition","register":"regional","registerEn":"regional","example":"A: この傘、めげた。 B: 予備を使おう。","exampleEn":"A: This umbrella broke. B: Let’s use the spare.","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"tango","phrase":"ぼじる","reading":"Bojiru","standard":"もぎ取る","english":"pluck; pick off","scene":"収穫","sceneEn":"Harvesting","tag":"action","register":"regional","registerEn":"regional","example":"A: 庭の実をぼじろう。 B: かごを持ってくる。","exampleEn":"A: Let’s pick the fruit in the garden. B: I’ll bring a basket.","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"tango","phrase":"なつべる","reading":"Natsuberu","standard":"片づける","english":"put away; tidy up","scene":"片づけ","sceneEn":"Tidying up","tag":"cleanup","register":"regional","registerEn":"regional","example":"A: 道具をなつべよう。 B: 棚を空けるね。","exampleEn":"A: Let’s put away the tools. B: I’ll clear the shelf.","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"tango","phrase":"かったに","reading":"Katta ni","standard":"全く","english":"completely; at all","scene":"予定","sceneEn":"Plans","tag":"emphasis","register":"regional","registerEn":"regional","example":"A: 今日はかったに予定がない。 B: 散歩でもしようか。","exampleEn":"A: I have no plans at all today. B: Shall we take a walk?","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"tango","phrase":"がしゃー","reading":"Gashā","standard":"とても","english":"very","scene":"天気","sceneEn":"Weather","tag":"emphasis","register":"regional","registerEn":"regional","example":"A: 今日はがしゃー暑いね。 B: 日陰で待とう。","exampleEn":"A: It’s very hot today. B: Let’s wait in the shade.","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"tango","phrase":"にゃーしょ","reading":"Nyāsho","standard":"内緒","english":"secret","scene":"贈り物","sceneEn":"Gifts","tag":"daily","register":"regional","registerEn":"regional","example":"A: 贈り物のことはにゃーしょにしてね。 B: わかった。","exampleEn":"A: Keep the gift a secret. B: Okay.","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"tango","phrase":"うみゃー","reading":"Umyā","standard":"うまい、おいしい","english":"tasty; delicious","scene":"食事","sceneEn":"Meals","tag":"food","register":"regional","registerEn":"regional","example":"A: このりんご、うみゃーね。 B: もう一つあるよ。","exampleEn":"A: This apple is delicious. B: There’s another one.","note":"市の副読本に掲載。世代による使用差あり。","noteEn":"Municipal reader; generational usage varies.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/43/chiikigakusyuuhukudokuhon.pdf","sourceTitle":"京丹後市：地域学習副読本「方言〜丹後弁〜」"},{"region":"nagoya","phrase":"うでる","reading":"Uderu","standard":"ゆでる","english":"boil","scene":"料理","sceneEn":"Cooking","tag":"action","register":"regional","registerEn":"regional","example":"A: 卵をうでるね。 B: 鍋を出しておくよ。","exampleEn":"A: I’ll boil the eggs. B: I’ll get the saucepan.","note":"市の比較資料で尾張の語として確認。","noteEn":"Official comparison attests this Owari word.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/3/201409.pdf","sourceTitle":"京丹後市広報：丹後ことばと尾張ことばに共通する主な言葉の例"},{"region":"nagoya","phrase":"こそばいい","reading":"Kosobaii","standard":"くすぐったい","english":"ticklish","scene":"感覚","sceneEn":"Sensations","tag":"body","register":"regional","registerEn":"regional","example":"A: 羽で触れるとこそばいい。 B: 柔らかい羽だね。","exampleEn":"A: The feather feels ticklish. B: It’s a soft feather.","note":"市の比較資料で尾張の語として確認。","noteEn":"Official comparison attests this Owari word.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/3/201409.pdf","sourceTitle":"京丹後市広報：丹後ことばと尾張ことばに共通する主な言葉の例"},{"region":"nagoya","phrase":"どべ","reading":"Dobe","standard":"最下位","english":"last place","scene":"ゲーム","sceneEn":"Games","tag":"quantity","register":"regional","registerEn":"regional","example":"A: 今回はどべだった。 B: 次の回もやろう。","exampleEn":"A: I came last this time. B: Let’s play another round.","note":"市の比較資料で尾張の語として確認。","noteEn":"Official comparison attests this Owari word.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/3/201409.pdf","sourceTitle":"京丹後市広報：丹後ことばと尾張ことばに共通する主な言葉の例"},{"region":"nagoya","phrase":"わや","reading":"Waya","standard":"めちゃくちゃ","english":"a mess; chaotic","scene":"片づけ","sceneEn":"Tidying up","tag":"condition","register":"regional","registerEn":"regional","example":"A: 引き出しの中がわやだ。 B: 一緒に整理しよう。","exampleEn":"A: The drawer is a mess. B: Let’s organize it together.","note":"市の比較資料で尾張の語として確認。","noteEn":"Official comparison attests this Owari word.","sourceUrl":"https://www.city.kyotango.lg.jp/material/files/group/3/201409.pdf","sourceTitle":"京丹後市広報：丹後ことばと尾張ことばに共通する主な言葉の例"},{"region":"nagoya","phrase":"ケッタ","reading":"Ketta","standard":"自転車","english":"bicycle","scene":"移動","sceneEn":"Getting around","tag":"daily","register":"regional","registerEn":"regional","example":"A: 駅までケッタで行くよ。 B: 駐輪場で待っているね。","exampleEn":"A: I’ll cycle to the station. B: I’ll wait at the bike parking area.","note":"名古屋市図書館が自転車の呼び名として確認。","noteEn":"The city library documents this bicycle word.","sourceUrl":"https://www.library.city.nagoya.jp/reference/chosahoukoku/chosahoukoku_139.html","sourceTitle":"名古屋市図書館：調査団報告書No.139「ケッタ」"},{"region":"wakayama","phrase":"おいやん","reading":"Oiyan","standard":"おじ（伯父・叔父）","english":"uncle","scene":"家族","sceneEn":"Family","tag":"daily","register":"regional","registerEn":"regional","example":"A: 誰と旅行したの？ B: おいやんと行ったよ。","exampleEn":"A: Who did you travel with? B: My uncle.","note":"県の広域語彙欄に掲載。地域・世代差あり。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://wave.pref.wakayama.lg.jp/bunka-archive/hougen/kana/kana1.html","sourceTitle":"和歌山県文化情報アーカイブ：方言50音順「あ」"},{"region":"wakayama","phrase":"おとんぼ","reading":"Otonbo","standard":"末っ子","english":"youngest child","scene":"家族","sceneEn":"Family","tag":"daily","register":"regional","registerEn":"regional","example":"A: 三人きょうだいなの？ B: うん、私はおとんぼ。","exampleEn":"A: Are there three siblings? B: Yes, I’m the youngest.","note":"県の広域語彙欄に掲載。地域・世代差あり。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://wave.pref.wakayama.lg.jp/bunka-archive/hougen/kana/kana1.html","sourceTitle":"和歌山県文化情報アーカイブ：方言50音順「あ」"},{"region":"wakayama","phrase":"くちなわ","reading":"Kuchinawa","standard":"蛇","english":"snake","scene":"自然","sceneEn":"Nature","tag":"animal","register":"regional","registerEn":"regional","example":"A: 写真のくちなわ、見える？ B: 木の下にいるね。","exampleEn":"A: Can you see the snake in the photo? B: Under the tree.","note":"県の広域語彙欄に掲載。地域・世代差あり。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://wave.pref.wakayama.lg.jp/bunka-archive/hougen/kana/kana2.html","sourceTitle":"和歌山県文化情報アーカイブ：方言50音順「か」"},{"region":"wakayama","phrase":"さいら","reading":"Saira","standard":"さんま","english":"Pacific saury","scene":"魚屋","sceneEn":"Fish market","tag":"food","register":"regional","registerEn":"regional","example":"A: さいらを二匹ください。 B: はい、袋に入れます。","exampleEn":"A: Two saury, please. B: Certainly, I’ll bag them.","note":"県の広域語彙欄に掲載。地域・世代差あり。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://wave.pref.wakayama.lg.jp/bunka-archive/hougen/kana/kana3.html","sourceTitle":"和歌山県文化情報アーカイブ：方言50音順「さ」"},{"region":"wakayama","phrase":"そこまめ","reading":"Sokomame","standard":"落花生","english":"peanuts","scene":"買い物","sceneEn":"Shopping","tag":"food","register":"regional","registerEn":"regional","example":"A: そこまめはこの棚？ B: うん、その袋だよ。","exampleEn":"A: Are the peanuts on this shelf? B: Yes, that bag.","note":"県の広域語彙欄に掲載。地域・世代差あり。","noteEn":"Prefectural glossary; local usage varies.","sourceUrl":"https://wave.pref.wakayama.lg.jp/bunka-archive/hougen/kana/kana3.html","sourceTitle":"和歌山県文化情報アーカイブ：方言50音順「さ」"},{"region":"wakayama","phrase":"ばっち","reading":"Batchi","standard":"股引","english":"long underwear","scene":"衣服","sceneEn":"Clothes","tag":"daily","register":"regional","registerEn":"regional","example":"A: 展示にあるばっちって？ B: 股引のことだよ。","exampleEn":"A: What is “batchi” in the display? B: Long underwear.","note":"股引を指す地域語。","noteEn":"A local word for long underwear.","sourceUrl":"https://wave.pref.wakayama.lg.jp/bunka-archive/hougen/kana/kana6.html","sourceTitle":"和歌山県文化情報アーカイブ：方言50音順「は」"},{"region":"enshu","phrase":"まるさら","reading":"Marusara","standard":"全部、まるごと","english":"all; the whole thing","scene":"荷物","sceneEn":"Luggage","tag":"quantity","register":"regional","registerEn":"regional","example":"A: この箱、まるさら持っていく？ B: うん、全部必要だよ。","exampleEn":"A: Shall we take this whole box? B: Yes, we need everything.","note":"浜松市が「全部、まるごと」と説明。","noteEn":"Hamamatsu defines it as all or whole.","sourceUrl":"https://www.city.hamamatsu.shizuoka.jp/koho2/room/interview/26/1224.html","sourceTitle":"浜松市：2014年12月定例記者会見"},{"region":"enshu","phrase":"いいとこだに","reading":"Ii toko da ni","standard":"いい所だよ","english":"It’s a nice place.","scene":"街の紹介","sceneEn":"Introducing a place","tag":"compliment","register":"regional","registerEn":"regional","example":"A: この町はどう？ B: いいとこだに。公園も近いよ。","exampleEn":"A: What’s this town like? B: It’s a nice place. The park is close too.","note":"「だに」は相手に知らせる「だよ」。","noteEn":"Dani presents information, like dayo.","sourceUrl":"https://www.city.hamamatsu.shizuoka.jp/koho2/pr/tiktok/index.html","sourceTitle":"浜松市公式TikTok「いいとこだに、浜松」"},{"region":"sado","phrase":"そうだっちゃ","reading":"Sō datcha","standard":"そうです、そのとおりです","english":"That’s right.","scene":"確認","sceneEn":"Confirmation","tag":"agreement","register":"regional","registerEn":"regional","example":"A: 集合は九時だったね。 B: そうだっちゃ。","exampleEn":"A: We’re meeting at nine, right? B: That’s right.","note":"県の佐渡地域振興局が意味を明示。","noteEn":"Explicitly glossed by the Sado regional bureau.","sourceUrl":"https://www.pref.niigata.lg.jp/sec/sado_kenko/so.html","sourceTitle":"新潟県：佐渡食育かるた「そ」"},{"region":"sado","phrase":"だちかんちゃ","reading":"Dachikancha","standard":"駄目だ、らちがあかない","english":"That won’t work.","scene":"作業","sceneEn":"Tasks","tag":"negative","register":"regional","registerEn":"regional","example":"A: この方法で進められる？ B: だちかんちゃ。別の方法を試そう。","exampleEn":"A: Can we proceed this way? B: That won’t work. Let’s try another way.","note":"うまくいかないことを表す。","noteEn":"Expresses that something will not work.","sourceUrl":"https://www.pref.niigata.lg.jp/sec/sado_kenko/so.html","sourceTitle":"新潟県：佐渡食育かるた「そ」"},{"region":"sado","phrase":"うみゃー","reading":"Umyā","standard":"うまい、おいしい","english":"tasty; delicious","scene":"食事","sceneEn":"Meals","tag":"food","register":"regional","registerEn":"regional","example":"A: このおにぎり、うみゃー。 B: もう一つどうぞ。","exampleEn":"A: This rice ball is delicious. B: Have another.","note":"佐渡内でも「うめぇー」などの形がある。","noteEn":"Pronunciation varies within Sado.","sourceUrl":"https://www.pref.niigata.lg.jp/sec/sado_kenko/so.html","sourceTitle":"新潟県：佐渡食育かるた「そ」"},{"region":"okayama","phrase":"もんげー大きいね","reading":"Mongē ōkii ne","standard":"ものすごく大きいね","english":"It is amazingly big.","scene":"買い物・大きさ","sceneEn":"Shopping · size","tag":"emphasis","register":"regional","registerEn":"regional","example":"A: このスイカを見て。 B: もんげー大きいね。","exampleEn":"A: Look at this watermelon. B: It is amazingly big.","note":"「もんげー」は強い程度を表す。岡山市の教材に掲載。","noteEn":"“Mongē” intensifies degree; listed in Okayama City’s primer.","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"okayama","phrase":"この枝、ふてーね","reading":"Kono eda, futē ne","standard":"この枝、太いね","english":"This branch is thick.","scene":"庭・自然","sceneEn":"Garden · nature","tag":"adjective","register":"regional","registerEn":"regional","example":"A: この枝を描こう。 B: この枝、ふてーね。","exampleEn":"A: Let us draw this branch. B: It is thick.","note":"「太い」の連母音が変化した形。岡山市の教材の例。","noteEn":"A local sound form of “futoi”; illustrated by Okayama City.","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"okayama","phrase":"このひも、なげーね","reading":"Kono himo, nagē ne","standard":"このひも、長いね","english":"This cord is long.","scene":"片付け・道具","sceneEn":"Tidying · tools","tag":"adjective","register":"regional","registerEn":"regional","example":"A: ひもは足りる？ B: このひも、なげーね。十分あるよ。","exampleEn":"A: Is the cord long enough? B: This one is long. We have enough.","note":"「長い」が「なげー」になる音形。地域の音を聞く練習。","noteEn":"“Nagai” becomes “nagē” in this local sound pattern.","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"okayama","phrase":"今日はあちーね","reading":"Kyō wa achī ne","standard":"今日は暑いね","english":"It is hot today.","scene":"天気","sceneEn":"Weather","tag":"condition","register":"regional","registerEn":"regional","example":"A: 外の様子は？ B: 今日はあちーね。","exampleEn":"A: What is it like outside? B: It is hot today.","note":"「暑い」の音形。教材では「うい」が「いー」になる例。","noteEn":"A local form of “atsui”; the primer illustrates ui → ī.","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"okayama","phrase":"朝はさみーね","reading":"Asa wa samī ne","standard":"朝は寒いね","english":"Mornings are cold.","scene":"天気・朝","sceneEn":"Weather · morning","tag":"condition","register":"regional","registerEn":"regional","example":"A: 朝も窓を開ける？ B: 朝はさみーね。少しだけにしよう。","exampleEn":"A: Shall we open the window in the morning too? B: Mornings are cold. Just a little.","note":"「寒い」の音形。岡山市の教材に掲載。","noteEn":"A local sound form of “samui” in Okayama City’s primer.","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"okayama","phrase":"いぬ","reading":"Inu","standard":"帰る・去る","english":"To go home; to leave.","scene":"移動・語彙","sceneEn":"Movement · vocabulary","tag":"action","register":"regional","registerEn":"regional","example":"A: 「いぬ」は犬のこと？ B: この会話では、帰るという意味だよ。","exampleEn":"A: Does “inu” mean a dog? B: In this conversation, it means to go home.","note":"ここでは動詞。「犬」と同じ音でも文脈で区別する。","noteEn":"Here it is a verb; context distinguishes it from “dog.”","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"okayama","phrase":"みられー","reading":"Mirarē","standard":"見なさい","english":"Have a look.","scene":"展示・案内","sceneEn":"Exhibits · guidance","tag":"instruction","register":"regional","registerEn":"regional","example":"A: どの写真を見るの？ B: 「みられー」は、見なさいという意味だよ。","exampleEn":"A: Which picture should I look at? B: “Mirarē” means have a look.","note":"備前の命令形として掲載。備中・美作では別の形も使う。","noteEn":"Listed for Bizen; Bitchū and Mimasaka have other forms.","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"okayama","phrase":"こられー","reading":"Korarē","standard":"来なさい","english":"Come here.","scene":"招待・語彙","sceneEn":"Invitation · vocabulary","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 「こられー」と呼ばれたよ。 B: こちらへ来なさいという意味だね。","exampleEn":"A: Someone called “korarē” to me. B: That means come here.","note":"備前の形。標準語の可能・尊敬の「来られる」と区別。","noteEn":"A Bizen directive; distinguish it from standard “korareru.”","sourceUrl":"https://okayama-life.jp/dialect","sourceTitle":"岡山市移住支援サイト「岡山弁講座」"},{"region":"tottori-city","phrase":"アソバイヤ","reading":"Asobaiya","standard":"遊ぼう","english":"Let us play.","scene":"友だち・遊び","sceneEn":"Friends · play","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 明日は何をする？ B: アソバイヤ。公園に行こう。","exampleEn":"A: What shall we do tomorrow? B: Let us play. Let us go to the park.","note":"因幡欄の「遊ぼう」。伯耆欄では「アスバイヤ」。","noteEn":"The Inaba invitation; Hōki’s listed form is “asubaiya.”","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"tottori-city","phrase":"スンマセン","reading":"Sunmasen","standard":"ありがとう","english":"Thank you.","scene":"手伝い・お礼","sceneEn":"Help · thanks","tag":"thanks","register":"regional","registerEn":"regional","example":"A: 荷物を運んでおいたよ。 B: スンマセン。助かりました。","exampleEn":"A: I carried the bags for you. B: Thank you. That helped.","note":"因幡欄では感謝。謝罪の標準語と文脈で区別する。","noteEn":"The Inaba table gives thanks; context distinguishes an apology.","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"tottori-city","phrase":"キガワルイ","reading":"Kigawarui","standard":"うるさい","english":"Noisy.","scene":"音・日常","sceneEn":"Noise · daily life","tag":"condition","register":"regional","registerEn":"regional","example":"A: 工事の音はどう？ B: 「キガワルイ」は、うるさいという意味だよ。","exampleEn":"A: How is the construction noise? B: “Kigawarui” means noisy.","note":"鳥取県の表で因幡・伯耆の両欄に掲載。","noteEn":"Listed in both the Inaba and Hōki columns.","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"tottori-city","phrase":"オットロシイ","reading":"Ottoroshii","standard":"おそろしい","english":"Frightening.","scene":"物語・感想","sceneEn":"Stories · reactions","tag":"feeling","register":"regional","registerEn":"regional","example":"A: この話、どうだった？ B: オットロシイ。でも続きを聞きたい。","exampleEn":"A: What did you think of the story? B: Frightening. But I want to hear the rest.","note":"因幡欄の「おそろしい」。地域の音形を学ぶ項目。","noteEn":"The Inaba column’s form meaning frightening.","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"tottori-city","phrase":"クタブレル","reading":"Kutabureru","standard":"疲れる","english":"To get tired.","scene":"散歩・休憩","sceneEn":"Walking · breaks","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 「クタブレル」はどういう意味？ B: 疲れるという意味だよ。","exampleEn":"A: What does “kutabureru” mean? B: To get tired.","note":"鳥取県の因幡・伯耆両欄で「疲れる」と説明。","noteEn":"Tottori’s table gives “get tired” for Inaba and Hōki.","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"yonago","phrase":"アスバイヤ","reading":"Asubaiya","standard":"遊ぼう","english":"Let us play.","scene":"友だち・遊び","sceneEn":"Friends · play","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 午後の予定は？ B: アスバイヤ。ボールを持ってきて。","exampleEn":"A: What are the afternoon plans? B: Let us play. Bring a ball.","note":"伯耆欄の「遊ぼう」。米子は鳥取県西部の項目として掲載。","noteEn":"The Hōki form, placed in the western Tottori entry.","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"yonago","phrase":"がいな箱","reading":"Gaina hako","standard":"大きな箱","english":"A big box.","scene":"荷物・大きさ","sceneEn":"Bags · size","tag":"adjective","register":"regional","registerEn":"regional","example":"A: 何が届いたの？ B: がいな箱だね。中を見てみよう。","exampleEn":"A: What arrived? B: A big box. Let us look inside.","note":"「がいな」は伯耆欄の「大きな」。米子市の命名説明でも確認可能。","noteEn":"“Gaina” means large in Hōki, also attested by Yonago City.","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"yonago","phrase":"カンニンエ","reading":"Kannin e","standard":"ごめん","english":"Sorry.","scene":"友だち・謝罪","sceneEn":"Friends · apology","tag":"care","register":"regional","registerEn":"regional","example":"A: 約束を忘れてしまった。カンニンエ。 B: 次はメモしておこう。","exampleEn":"A: I forgot our plan. Sorry. B: Let us write it down next time.","note":"伯耆欄の謝罪表現。場面に応じて標準語の丁寧な謝罪も使う。","noteEn":"The Hōki apology; choose appropriate politeness for the situation.","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"yonago","phrase":"朝はサビ","reading":"Asa wa sabi","standard":"朝は寒い","english":"Mornings are cold.","scene":"天気・朝","sceneEn":"Weather · morning","tag":"condition","register":"regional","registerEn":"regional","example":"A: 朝の散歩はどう？ B: 朝はサビ。上着を持っていこう。","exampleEn":"A: How about a morning walk? B: Mornings are cold. Let us bring jackets.","note":"伯耆欄では「寒い」が「サビ」。因幡の「サブイ」と区別。","noteEn":"Hōki’s “sabi” means cold; Inaba’s listed form is “sabui.”","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"yonago","phrase":"キョートイ","reading":"Kyōtoi","standard":"おそろしい","english":"Frightening.","scene":"物語・反応","sceneEn":"Stories · reactions","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 暗い森の場面だったね。 B: キョートイ。明るい場面も見たい。","exampleEn":"A: That scene was in a dark forest. B: Frightening. I want a brighter scene too.","note":"伯耆欄の「おそろしい」。同欄には「キョテ」もある。","noteEn":"Hōki’s form meaning frightening; the table also lists “kyote.”","sourceUrl":"https://www.pref.tottori.lg.jp/28531.htm","sourceTitle":"鳥取県「鳥取県の文化・伝統」方言表"},{"region":"shunan","phrase":"ひもをきびる","reading":"Himo o kibiru","standard":"ひもを結ぶ","english":"To tie a cord.","scene":"荷物・作業","sceneEn":"Bags · tasks","tag":"action","register":"regional","registerEn":"regional","example":"A: ひもをきびる、はどういう意味？ B: ひもを結ぶという意味だよ。","exampleEn":"A: What does “himo o kibiru” mean? B: To tie a cord.","note":"「きびる」は結ぶ・縛る。周南中心の語彙資料。","noteEn":"“Kibiru” means tie or bind in the Shūnan-centered reference.","sourceUrl":"https://hagilib.city.hagi.lg.jp/hagilib-archive/image/863.pdf","sourceTitle":"阿部啓治「てれんこぽれんこ山口弁」（萩市立図書館公開）"},{"region":"shunan","phrase":"みやすい作業","reading":"Miyasui sagyō","standard":"簡単な作業","english":"An easy task.","scene":"仕事・難易度","sceneEn":"Work · difficulty","tag":"work","register":"regional","registerEn":"regional","example":"A: この作業は難しい？ B: みやすい作業だよ。順番にやろう。","exampleEn":"A: Is this task hard? B: It is easy. Let us do it step by step.","note":"ここでは「容易な」の意味。「見えやすい」と混同しない。","noteEn":"Here it means easy, rather than visually easy to see.","sourceUrl":"https://hagilib.city.hagi.lg.jp/hagilib-archive/image/863.pdf","sourceTitle":"阿部啓治「てれんこぽれんこ山口弁」（萩市立図書館公開）"},{"region":"shunan","phrase":"ねき","reading":"Neki","standard":"そば・横","english":"Beside; nearby.","scene":"場所・語彙","sceneEn":"Location · vocabulary","tag":"existence","register":"regional","registerEn":"regional","example":"A: 「ねき」ってどこ？ B: そばや横のことだよ。","exampleEn":"A: Where is “neki”? B: Beside or nearby.","note":"「際・脇・横・側」の語として掲載。位置の聞き取り用。","noteEn":"Listed for edge, side or beside; a location word.","sourceUrl":"https://hagilib.city.hagi.lg.jp/hagilib-archive/image/863.pdf","sourceTitle":"阿部啓治「てれんこぽれんこ山口弁」（萩市立図書館公開）"},{"region":"shunan","phrase":"この味、むつこいね","reading":"Kono aji, mutsukoi ne","standard":"この味、くどいね","english":"This flavor is too rich.","scene":"食事・感想","sceneEn":"Meals · reactions","tag":"food","register":"regional","registerEn":"regional","example":"A: 味はどう？ B: この味、むつこいね。私は少しだけにする。","exampleEn":"A: How is the flavor? B: It is too rich. I will have just a little.","note":"食べ物では味のしつこさを表す。周南中心の資料。","noteEn":"For food, it describes an overly rich or cloying taste.","sourceUrl":"https://hagilib.city.hagi.lg.jp/hagilib-archive/image/863.pdf","sourceTitle":"阿部啓治「てれんこぽれんこ山口弁」（萩市立図書館公開）"},{"region":"shunan","phrase":"はぶてる","reading":"Habuteru","standard":"ふくれる・むくれる","english":"To sulk.","scene":"気持ち・語彙","sceneEn":"Feelings · vocabulary","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 「はぶてる」は怒ること？ B: ふくれる、むくれるという意味だよ。","exampleEn":"A: Does “habuteru” mean get angry? B: It means to sulk.","note":"感情の様子を表す語。相手を決めつける言い方には注意。","noteEn":"A word for sulking; avoid labeling someone carelessly.","sourceUrl":"https://hagilib.city.hagi.lg.jp/hagilib-archive/image/863.pdf","sourceTitle":"阿部啓治「てれんこぽれんこ山口弁」（萩市立図書館公開）"},{"region":"shunan","phrase":"しあわせます","reading":"Shiawasemasu","standard":"ありがたいです・助かります","english":"I appreciate it; that helps.","scene":"依頼・お礼","sceneEn":"Requests · thanks","tag":"thanks","register":"regional","registerEn":"regional","example":"A: 明日、手伝えます。 B: しあわせます。では十時にお願いします。","exampleEn":"A: I can help tomorrow. B: I appreciate it. Then ten, please.","note":"感謝や好都合の意味を含む。周南中心の資料に掲載。","noteEn":"Expresses appreciation or convenience in the Shūnan-centered reference.","sourceUrl":"https://hagilib.city.hagi.lg.jp/hagilib-archive/image/863.pdf","sourceTitle":"阿部啓治「てれんこぽれんこ山口弁」（萩市立図書館公開）"},{"region":"shunan","phrase":"あずる","reading":"Azuru","standard":"てこずる・四苦八苦する","english":"To struggle with a task.","scene":"作業・進み具合","sceneEn":"Tasks · progress","tag":"work","register":"regional","registerEn":"regional","example":"A: 「あずる」は何をしているの？ B: てこずっているという意味だよ。","exampleEn":"A: What is happening when someone says “azuru”? B: They are struggling with a task.","note":"作業に難儀する語。資料には古い使用語も含まれる。","noteEn":"Describes struggling; the reference includes older usage too.","sourceUrl":"https://hagilib.city.hagi.lg.jp/hagilib-archive/image/863.pdf","sourceTitle":"阿部啓治「てれんこぽれんこ山口弁」（萩市立図書館公開）"},{"region":"kagawa","phrase":"こんまい箱","reading":"Konmai hako","standard":"小さい箱","english":"A small box.","scene":"買い物・大きさ","sceneEn":"Shopping · size","tag":"adjective","register":"regional","registerEn":"regional","example":"A: 大きい箱が必要？ B: こんまい箱で十分だよ。","exampleEn":"A: Do we need a big box? B: A small one is enough.","note":"「こんまい」は小さい。香川県の教育教材に掲載。","noteEn":"“Konmai” means small in Kagawa’s education material.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"けっこい花","reading":"Kekkoi hana","standard":"きれいな花","english":"A beautiful flower.","scene":"庭・感想","sceneEn":"Garden · reactions","tag":"compliment","register":"regional","registerEn":"regional","example":"A: 花が咲いたね。 B: けっこい花だね。写真を撮ろう。","exampleEn":"A: The flowers bloomed. B: A beautiful flower. Let us take a picture.","note":"「けっこい」はきれいなという意味。地域語彙の練習。","noteEn":"“Kekkoi” means beautiful; a regional vocabulary exercise.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"さらのノート","reading":"Sara no nōto","standard":"新しいノート","english":"A new notebook.","scene":"学習・文具","sceneEn":"Learning · stationery","tag":"daily","register":"regional","registerEn":"regional","example":"A: 今日から何に書く？ B: さらのノートに書こう。","exampleEn":"A: What shall we write in today? B: Let us use a new notebook.","note":"「さら」は新しい。食器の「皿」とは文脈で区別。","noteEn":"“Sara” means new; context distinguishes it from a plate.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"まんでがん","reading":"Mandegan","standard":"残らず全部","english":"Every last bit; all of it.","scene":"片付け・量","sceneEn":"Tidying · quantity","tag":"quantity","register":"regional","registerEn":"regional","example":"A: どれを持っていくの？ B: 「まんでがん」は全部という意味だよ。","exampleEn":"A: Which ones are we taking? B: “Mandegan” means all of them.","note":"全部を表す副詞。香川県教材の語形。","noteEn":"An adverb meaning all of it in Kagawa’s material.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"ごはんをつぐ","reading":"Gohan o tsugu","standard":"ごはんを盛る","english":"To serve rice.","scene":"食事・配膳","sceneEn":"Meals · serving","tag":"action","register":"regional","registerEn":"regional","example":"A: ごはんをつぐ、って？ B: ごはんを茶わんに盛ることだよ。","exampleEn":"A: What does “gohan o tsugu” mean? B: To put rice in a bowl.","note":"教材では「ごはんを盛る・よそう」と説明。","noteEn":"The material glosses it as serving rice into a bowl.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"箱にしのべる","reading":"Hako ni shinoberu","standard":"箱に片付ける","english":"To put away in a box.","scene":"片付け・道具","sceneEn":"Tidying · tools","tag":"cleanup","register":"regional","registerEn":"regional","example":"A: 道具はどうする？ B: 「しのべる」は片付けるという意味だよ。","exampleEn":"A: What about the tools? B: “Shinoberu” means put away.","note":"「しのべる」は片付ける・始末する。現代頻度は人による。","noteEn":"Means put away or dispose of; present-day frequency varies.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"ものご","reading":"Monogo","standard":"入れ物","english":"A container.","scene":"台所・道具","sceneEn":"Kitchen · tools","tag":"daily","register":"regional","registerEn":"regional","example":"A: 「ものご」は何？ B: 入れ物のこと。ここに小さい容器があるよ。","exampleEn":"A: What is “monogo”? B: A container. Here is a small one.","note":"入れ物を表す語。香川県教材に掲載。","noteEn":"A word for a container in Kagawa’s material.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"ひもをいわえる","reading":"Himo o iwaeru","standard":"ひもを結ぶ","english":"To tie a cord.","scene":"道具・作業","sceneEn":"Tools · tasks","tag":"action","register":"regional","registerEn":"regional","example":"A: ひもをいわえる、って？ B: 結ぶということだよ。","exampleEn":"A: What does “himo o iwaeru” mean? B: To tie a cord.","note":"「いわえる」は結ぶ。周囲の会話は標準語の学習例。","noteEn":"“Iwaeru” means tie; the surrounding learning dialogue is standard Japanese.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"いきし","reading":"Ikishi","standard":"行く途中","english":"On the way there.","scene":"移動・予定","sceneEn":"Movement · plans","tag":"daily","register":"regional","registerEn":"regional","example":"A: 「いきし」はいつのこと？ B: 行く途中のことだよ。","exampleEn":"A: When is “ikishi”? B: On the way there.","note":"行く途中を指す。帰りの途中と区別して覚える。","noteEn":"Means on the outward journey; distinguish it from the return.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"kagawa","phrase":"でぼちん","reading":"Debochin","standard":"ひたい","english":"Forehead.","scene":"からだ・語彙","sceneEn":"Body · vocabulary","tag":"body","register":"regional","registerEn":"regional","example":"A: 絵の「でぼちん」はどこ？ B: ひたいのことだよ。","exampleEn":"A: Where is “debochin” in the drawing? B: The forehead.","note":"身体語彙。香川県教材の「からだ特集」に掲載。","noteEn":"A body word in Kagawa’s illustrated body vocabulary section.","sourceUrl":"https://www.pref.kagawa.lg.jp/documents/14715/76_77.pdf","sourceTitle":"香川県教育委員会「ふるさと香川」香川（讃岐）の方言 pp.76–77"},{"region":"tokushima","phrase":"ほなけん","reading":"Honaken","standard":"だから","english":"So; therefore.","scene":"理由・語彙","sceneEn":"Reasons · vocabulary","tag":"reason","register":"regional","registerEn":"regional","example":"A: 「ほなけん」はどういう意味？ B: だから、という意味だよ。","exampleEn":"A: What does “honaken” mean? B: So or therefore.","note":"佐那河内村の公式記事が阿波弁の例として掲載。","noteEn":"Listed as an Awa expression by Sanagōchi Village.","sourceUrl":"https://www.vill.sanagochi.lg.jp/docs/2022071500041/","sourceTitle":"佐那河内村「村の方言『ひどい』」"},{"region":"tokushima","phrase":"どちらいか","reading":"Dochiraika","standard":"どういたしまして","english":"You are welcome.","scene":"お礼への返事","sceneEn":"Replying to thanks","tag":"thanks","register":"regional","registerEn":"regional","example":"A: 手伝ってくれてありがとう。 B: どちらいか。また声をかけてね。","exampleEn":"A: Thank you for helping. B: You are welcome. Ask me again anytime.","note":"阿波弁の返礼表現として村の公式記事に掲載。","noteEn":"Listed as an Awa response to thanks in the village article.","sourceUrl":"https://www.vill.sanagochi.lg.jp/docs/2022071500041/","sourceTitle":"佐那河内村「村の方言『ひどい』」"},{"region":"tokushima","phrase":"ひどいな","reading":"Hidoi na","standard":"それは大変でしたね","english":"That must have been hard.","scene":"ねぎらい・会話","sceneEn":"Acknowledging effort · conversation","tag":"care","register":"regional","registerEn":"regional","example":"A: 昨日は一日中、引っ越しの準備だった。 B: ひどいな。","exampleEn":"A: I prepared for the move all day yesterday. B: That must have been hard.","note":"佐那河内村のねぎらい用法。徳島全域の用法とはしない。","noteEn":"Sanagōchi’s empathetic use; not a claim for all Tokushima.","sourceUrl":"https://www.vill.sanagochi.lg.jp/docs/2022071500041/","sourceTitle":"佐那河内村「村の方言『ひどい』」"},{"region":"karatsu","phrase":"がね","reading":"Gane","standard":"カニ","english":"Crab.","scene":"海・生き物","sceneEn":"Sea · wildlife","tag":"animal","register":"regional","registerEn":"regional","example":"A: 写真の「がね」は何？ B: カニのことだよ。","exampleEn":"A: What is “gane” in the photo? B: A crab.","note":"玄海町の歴史語彙表の「カニ」。北西部佐賀の一例。","noteEn":"“Crab” in Genkai Town’s historical lexicon; a local northwest Saga example.","sourceUrl":"https://www.town.genkai.lg.jp/site/kankou/88072.html","sourceTitle":"玄海町「玄海町の方言」"},{"region":"karatsu","phrase":"ぼうぶら","reading":"Bōbura","standard":"かぼちゃ","english":"Pumpkin.","scene":"台所・食材","sceneEn":"Kitchen · ingredients","tag":"food","register":"regional","registerEn":"regional","example":"A: 「ぼうぶら」を切ってあるよ。 B: かぼちゃのことだね。","exampleEn":"A: The “bōbura” is cut up. B: That means pumpkin.","note":"玄海町の歴史語彙表に掲載。全世代の頻用語とはしない。","noteEn":"Recorded by Genkai Town; universal present-day use is not claimed.","sourceUrl":"https://www.town.genkai.lg.jp/site/kankou/88072.html","sourceTitle":"玄海町「玄海町の方言」"},{"region":"karatsu","phrase":"てぼ","reading":"Tebo","standard":"ざる","english":"Basket; strainer.","scene":"台所・道具","sceneEn":"Kitchen · tools","tag":"daily","register":"regional","registerEn":"regional","example":"A: 「てぼ」はどの道具？ B: ここでは、ざるのことだよ。","exampleEn":"A: Which tool is a “tebo”? B: Here it means a basket or strainer.","note":"玄海町の表では「ざる」。道具名は地域で意味が変わる。","noteEn":"Genkai’s table gives a basket/strainer; tool names vary locally.","sourceUrl":"https://www.town.genkai.lg.jp/site/kankou/88072.html","sourceTitle":"玄海町「玄海町の方言」"},{"region":"karatsu","phrase":"よさり","reading":"Yosari","standard":"夜","english":"Night.","scene":"時間・語彙","sceneEn":"Time · vocabulary","tag":"daily","register":"regional","registerEn":"regional","example":"A: 「よさり」は朝？ B: 夜のことだよ。","exampleEn":"A: Is “yosari” morning? B: It means night.","note":"玄海町の歴史語彙。資料には古い語も含まれる。","noteEn":"A Genkai historical word; the source includes older vocabulary.","sourceUrl":"https://www.town.genkai.lg.jp/site/kankou/88072.html","sourceTitle":"玄海町「玄海町の方言」"},{"region":"karatsu","phrase":"ひだるか","reading":"Hidaruka","standard":"空腹だ","english":"Hungry.","scene":"食事・気持ち","sceneEn":"Meals · feelings","tag":"food","register":"regional","registerEn":"regional","example":"A: お昼にしようか。 B: ひだるか。もう食べたいね。","exampleEn":"A: Shall we have lunch? B: I am hungry. I want to eat now.","note":"玄海町の表では空腹・ひもじい。現代頻度は未確認。","noteEn":"Genkai’s table gives hungry; present-day frequency is unverified.","sourceUrl":"https://www.town.genkai.lg.jp/site/kankou/88072.html","sourceTitle":"玄海町「玄海町の方言」"},{"region":"karatsu","phrase":"おらぶ","reading":"Orabu","standard":"大声で呼ぶ","english":"To call out loudly.","scene":"呼びかけ・語彙","sceneEn":"Calling · vocabulary","tag":"action","register":"regional","registerEn":"regional","example":"A: 「おらぶ」はどういう意味？ B: 大声で呼ぶことだよ。","exampleEn":"A: What does “orabu” mean? B: To call out loudly.","note":"玄海町の歴史語彙表に掲載。地域・話者差がある。","noteEn":"Attested in Genkai’s historical lexicon; speakers and places vary.","sourceUrl":"https://www.town.genkai.lg.jp/site/kankou/88072.html","sourceTitle":"玄海町「玄海町の方言」"},{"region":"kumamoto","phrase":"来なっせ","reading":"Kinasse","standard":"来てください","english":"Please come.","scene":"招待・案内","sceneEn":"Invitation · guidance","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 今から行ってもいい？ B: 来なっせ。お茶を用意します。","exampleEn":"A: May I come now? B: Please come. I will make tea.","note":"2026年県教材では県全域の依頼表現として掲載。","noteEn":"The 2026 prefectural handbook marks this request for all areas.","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"kumamoto","phrase":"見てはいよ","reading":"Mite haiyo","standard":"見てください","english":"Please look.","scene":"展示・依頼","sceneEn":"Exhibits · requests","tag":"request","register":"regional","registerEn":"regional","example":"A: 写真を選んだよ。見てはいよ。 B: どれも明るいね。","exampleEn":"A: I chose some photos. Please look. B: They are all bright.","note":"県教材の「〜してはいよ」を標準語の動詞に接続した学習例。","noteEn":"A learning example of the handbook’s request ending “-shite haiyo.”","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"kumamoto","phrase":"はがいか","reading":"Hagaika","standard":"悔しい・腹立たしい","english":"Frustrating.","scene":"ゲーム・感想","sceneEn":"Games · reactions","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 最後の一問を間違えた。はがいか。 B: 次は一緒に考えよう。","exampleEn":"A: I missed the last question. Frustrating. B: Let us work together next time.","note":"県教材では悔しさ・腹立たしさの語。","noteEn":"The handbook glosses it as frustrated or annoyed.","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"kumamoto","phrase":"でけん","reading":"Deken","standard":"できない・だめ","english":"Cannot; no good.","scene":"予定・可否","sceneEn":"Plans · possibility","tag":"negative","register":"regional","registerEn":"regional","example":"A: 「でけん」は何が難しいの？ B: できない、だめという意味だよ。","exampleEn":"A: What is difficult when someone says “deken”? B: It means cannot or no good.","note":"不可を表す県全域表示の語。文脈で能力と禁止を区別。","noteEn":"Marked for all areas; context distinguishes inability from prohibition.","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"kumamoto","phrase":"おおごつ","reading":"Ōgotsu","standard":"大変なこと・おおごと","english":"A big problem.","scene":"仕事・反応","sceneEn":"Work · reactions","tag":"reaction","register":"regional","registerEn":"regional","example":"A: 保存したファイルが見つからない。 B: おおごつ。まず名前で探そう。","exampleEn":"A: I cannot find the saved file. B: A big problem. Let us search by its name.","note":"「大変・おおごと」。県教材の日常語彙。","noteEn":"Means a serious problem; daily vocabulary in the prefectural handbook.","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"kumamoto","phrase":"いっちょん分からない","reading":"Itchon wakaranai","standard":"全然分からない","english":"I do not understand at all.","scene":"学習・理解","sceneEn":"Learning · understanding","tag":"negative","register":"regional","registerEn":"regional","example":"A: この図の意味は？ B: いっちょん分からない。説明を読もう。","exampleEn":"A: What does this diagram mean? B: I do not understand at all. Let us read the explanation.","note":"「いっちょん」は全然。教材は県全域として掲載。","noteEn":"“Itchon” means not at all; marked for all areas.","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"aso","phrase":"確認せなん","reading":"Kakunin senan","standard":"確認しなければならない","english":"We need to check.","scene":"仕事・確認","sceneEn":"Work · checking","tag":"instruction","register":"regional","registerEn":"regional","example":"A: すぐ印刷していい？ B: 確認せなん。数字をもう一度見よう。","exampleEn":"A: Can I print it now? B: We need to check. Let us look at the numbers again.","note":"「せなん」は県北・県央の表示。阿蘇には県北の例として掲載。","noteEn":"Marked north/central Kumamoto; placed in Aso as a northern example.","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"aso","phrase":"しもうた","reading":"Shimōta","standard":"しまった・やってしまった","english":"Oh no; I messed up.","scene":"忘れ物・反応","sceneEn":"Forgotten items · reactions","tag":"reaction","register":"regional","registerEn":"regional","example":"A: しもうた。ノートを家に忘れた。 B: 紙を一枚あげるよ。","exampleEn":"A: Oh no. I left my notebook at home. B: I will give you a sheet of paper.","note":"県北・県央表示の語。阿蘇の全話者の使用を保証しない。","noteEn":"Marked north/central; not a claim about every Aso speaker.","sourceUrl":"https://www.pref.kumamoto.jp/uploaded/life/258611_794494_misc.pdf","sourceTitle":"熊本県「くまもと方言ハンドブック」2026年"},{"region":"kagoshima","phrase":"またごあんそ","reading":"Mata goanso","standard":"またお会いしましょう・さようなら","english":"See you again; goodbye.","scene":"別れ・挨拶","sceneEn":"Farewells · greetings","tag":"farewell","register":"regional","registerEn":"regional","example":"A: 今日はありがとうございました。 B: またごあんそ。","exampleEn":"A: Thank you for today. B: See you again.","note":"県リーフレットの薩摩・大隅欄に掲載した挨拶例。","noteEn":"A greeting example in the leaflet’s Satsuma/Ōsumi column.","sourceUrl":"https://www.pref.kagoshima.jp/ab10/kyoiku-bunka/bunka/shinko/documents/hougen.pdf","sourceTitle":"鹿児島県「かごしまの方言ミニ講座」"},{"region":"kagoshima","phrase":"あいがともさげもした","reading":"Aigato mosage moshita","standard":"ありがとうございました","english":"Thank you very much.","scene":"お礼・挨拶","sceneEn":"Thanks · greetings","tag":"thanks","register":"regional","registerEn":"regional","example":"A: 案内してくださって、あいがともさげもした。 B: また来てくださいね。","exampleEn":"A: Thank you very much for showing me around. B: Please come again.","note":"薩摩・大隅欄の丁寧なお礼の例。話者により形が違う。","noteEn":"A polite Satsuma/Ōsumi thanks example; forms differ by speaker.","sourceUrl":"https://www.pref.kagoshima.jp/ab10/kyoiku-bunka/bunka/shinko/documents/hougen.pdf","sourceTitle":"鹿児島県「かごしまの方言ミニ講座」"},{"region":"kagoshima","phrase":"うんだもしたん","reading":"Unda moshitan","standard":"わあ・びっくりした","english":"Wow; what a surprise.","scene":"驚き・反応","sceneEn":"Surprise · reactions","tag":"reaction","register":"regional","registerEn":"regional","example":"A: うんだもしたん。この写真、大きく印刷したね。 B: 展示用なんだ。","exampleEn":"A: Wow. You printed this photo large. B: It is for an exhibit.","note":"県リーフレットは驚いたときの表現として説明。","noteEn":"The prefectural leaflet labels it an expression of surprise.","sourceUrl":"https://www.pref.kagoshima.jp/ab10/kyoiku-bunka/bunka/shinko/documents/hougen.pdf","sourceTitle":"鹿児島県「かごしまの方言ミニ講座」"},{"region":"kagoshima","phrase":"どうか、おきばいやんせ","reading":"Dōka, okibaiyanse","standard":"どうか、頑張ってください","english":"Please do your best.","scene":"応援・挨拶","sceneEn":"Encouragement · greetings","tag":"encouragement","register":"regional","registerEn":"regional","example":"A: 明日、発表をします。 B: どうか、おきばいやんせ。","exampleEn":"A: I will give a presentation tomorrow. B: Please do your best.","note":"薩摩・大隅の例として県のリーフレットに掲載。","noteEn":"Listed as a Satsuma/Ōsumi encouragement in the prefectural leaflet.","sourceUrl":"https://www.pref.kagoshima.jp/ab10/kyoiku-bunka/bunka/shinko/documents/hougen.pdf","sourceTitle":"鹿児島県「かごしまの方言ミニ講座」"},{"region":"amami","phrase":"いもーりんしょうれ","reading":"Imōrinshōre","standard":"ようこそいらっしゃいました","english":"Welcome.","scene":"到着・挨拶","sceneEn":"Arrival · greeting","tag":"welcome","register":"regional","registerEn":"regional","example":"A: 奄美のことばを習っています。 B: 「いもーりんしょうれ」は歓迎の挨拶の例だよ。","exampleEn":"A: I am learning Amami words. B: “Imōrinshōre” is one example of a welcome.","note":"県の奄美欄の代表例。奄美諸島の島・集落差がある。","noteEn":"An Amami-column example; islands and communities have different forms.","sourceUrl":"https://www.pref.kagoshima.jp/ab10/kyoiku-bunka/bunka/shinko/documents/hougen.pdf","sourceTitle":"鹿児島県「かごしまの方言ミニ講座」"},{"region":"amami","phrase":"うがみんしょーら","reading":"Ugaminshōra","standard":"こんにちは","english":"Hello.","scene":"出会い・挨拶","sceneEn":"Meeting · greeting","tag":"greeting","register":"regional","registerEn":"regional","example":"A: 昼の挨拶も習いたい。 B: 県の資料には「うがみんしょーら」があるよ。","exampleEn":"A: I want to learn a daytime greeting too. B: The prefectural material lists “ugaminshōra.”","note":"奄美の挨拶例。日本語の鹿児島訛りと同一視しない。","noteEn":"An Amami greeting example; distinguish Amami language from Kagoshima Japanese.","sourceUrl":"https://www.pref.kagoshima.jp/ab10/kyoiku-bunka/bunka/shinko/documents/hougen.pdf","sourceTitle":"鹿児島県「かごしまの方言ミニ講座」"},{"region":"amami","phrase":"またうがみんしょーろ","reading":"Mata ugaminshōro","standard":"またお会いしましょう","english":"See you again.","scene":"別れ・挨拶","sceneEn":"Farewells · greeting","tag":"farewell","register":"regional","registerEn":"regional","example":"A: 別れの挨拶は？ B: この資料の奄美の例は「またうがみんしょーろ」だよ。","exampleEn":"A: What is the farewell? B: This material’s Amami example is “mata ugaminshōro.”","note":"県資料の奄美欄。全島共通の一つの方言とは扱わない。","noteEn":"The leaflet’s Amami column; not one shared dialect across every island.","sourceUrl":"https://www.pref.kagoshima.jp/ab10/kyoiku-bunka/bunka/shinko/documents/hougen.pdf","sourceTitle":"鹿児島県「かごしまの方言ミニ講座」"},{"region":"kochi-city","phrase":"ぼっちり","reading":"Botchiri","standard":"ちょうど良い・ぴったり","english":"Just right; a perfect fit.","scene":"買い物・サイズ","sceneEn":"Shopping · size","tag":"condition","register":"regional","registerEn":"regional","example":"A: この箱に全部入ったよ。 B: ぼっちり。ふたも閉まるね。","exampleEn":"A: Everything fits in this box. B: Just right. The lid closes too.","note":"高知市公式サイトが「ちょうど良い・ぴったり」と説明。","noteEn":"Kochi City explicitly glosses it as just right or a perfect fit.","sourceUrl":"https://www.city.kochi.kochi.jp/deeps/kochi-life/index.html","sourceTitle":"高知市移住支援サイト「こうちらいふ」"},{"region":"kochi-city","phrase":"いぬる","reading":"Inuru","standard":"帰る","english":"To go home.","scene":"移動・語彙","sceneEn":"Movement · vocabulary","tag":"action","register":"regional","registerEn":"regional","example":"A: 土佐の「いぬる」は何？ B: 帰るという意味だよ。","exampleEn":"A: What does Tosa’s “inuru” mean? B: To go home.","note":"春野郷土資料館の昔話注釈に掲載した土佐の語。","noteEn":"A Tosa word explained in Haruno Museum’s story notes.","sourceUrl":"https://www.city.kochi.kochi.jp/deeps/20/2019/muse/hanashi/hanashi38.html","sourceTitle":"高知市春野郷土資料館「ヒルマンぼうず」注釈"},{"region":"kochi-city","phrase":"だれる","reading":"Dareru","standard":"疲れる","english":"To get tired.","scene":"休憩・語彙","sceneEn":"Breaks · vocabulary","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 「だれる」は何を感じるの？ B: この土佐の用法では、疲れることだよ。","exampleEn":"A: What feeling does “dareru” describe? B: In this Tosa use, getting tired.","note":"春野資料館の注釈では「疲れる」。標準語の別義と区別。","noteEn":"Haruno’s notes give getting tired; distinguish other standard meanings.","sourceUrl":"https://www.city.kochi.kochi.jp/deeps/20/2019/muse/hanashi/hanashi38.html","sourceTitle":"高知市春野郷土資料館「ヒルマンぼうず」注釈"},{"region":"kochi-city","phrase":"おきゃく","reading":"Okyaku","standard":"宴会","english":"A party or banquet.","scene":"集まり・食事","sceneEn":"Gatherings · meals","tag":"food","register":"regional","registerEn":"regional","example":"A: 土佐の「おきゃく」はお客さん？ B: 宴会を指すことばだよ。","exampleEn":"A: Does Tosa’s “okyaku” mean a guest? B: It is a word for a party or banquet.","note":"高知市の用語解説では土佐弁の「宴会」。","noteEn":"Kochi City’s glossary gives the Tosa meaning party or banquet.","sourceUrl":"https://www.city.kochi.kochi.jp/joho/upload/files/0502/1205_pabukome_hp.pdf","sourceTitle":"高知市文化施策資料・用語解説「おきゃく」"},{"region":"miyazaki","phrase":"ゾップイ","reading":"Zoppui","standard":"ずぶ濡れの様子","english":"Soaking wet.","scene":"雨・状態","sceneEn":"Rain · condition","tag":"condition","register":"regional","registerEn":"regional","example":"A: 「ゾップイ」はどんな状態？ B: ずぶ濡れの様子を表すことばだよ。","exampleEn":"A: What state does “zoppui” describe? B: Soaking wet.","note":"国語研の一覧は宮崎・鹿児島に記録。県内頻度は未確認。","noteEn":"NINJAL lists Miyazaki/Kagoshima; local frequency is not established.","sourceUrl":"https://kotoba.ninjal.ac.jp/qa/yokuaru/qa-236/","sourceTitle":"国立国語研究所ことば研究館「オノマトペにも方言がありますか」"},{"region":"miyazaki","phrase":"ガッツイ","reading":"Gattsui","standard":"ぴったりする様子","english":"Fitting exactly.","scene":"サイズ・語彙","sceneEn":"Size · vocabulary","tag":"condition","register":"regional","registerEn":"regional","example":"A: サイズを表す「ガッツイ」は？ B: ぴったりする様子のことだよ。","exampleEn":"A: What does “gattsui” describe for size? B: Fitting exactly.","note":"国語研の宮崎・鹿児島の語形。「がっつり」と混同しない。","noteEn":"NINJAL lists Miyazaki/Kagoshima; distinguish it from standard “gattsuri.”","sourceUrl":"https://kotoba.ninjal.ac.jp/qa/yokuaru/qa-236/","sourceTitle":"国立国語研究所ことば研究館「オノマトペにも方言がありますか」"},{"region":"oita","phrase":"トンボラ","reading":"Tonbora","standard":"まばらな様子","english":"Sparse; scattered thinly.","scene":"配置・語彙","sceneEn":"Arrangement · vocabulary","tag":"quantity","register":"regional","registerEn":"regional","example":"A: 「トンボラ」は密集している？ B: まばらな様子を表すよ。","exampleEn":"A: Does “tonbora” mean densely packed? B: It describes sparse distribution.","note":"国語研の一覧が大分の語として掲載。細かい分布は未指定。","noteEn":"NINJAL lists it for Oita; finer geographic distribution is unspecified.","sourceUrl":"https://kotoba.ninjal.ac.jp/qa/yokuaru/qa-236/","sourceTitle":"国立国語研究所ことば研究館「オノマトペにも方言がありますか」"},{"region":"ehime","phrase":"ハツハツ","reading":"Hatsuhatsu","standard":"かろうじて達する様子","english":"Barely reaching.","scene":"距離・程度","sceneEn":"Distance · degree","tag":"condition","register":"regional","registerEn":"regional","example":"A: 「ハツハツ」は余裕がある？ B: かろうじて届くような様子だよ。","exampleEn":"A: Does “hatsuhatsu” mean there is plenty of margin? B: It means barely reaching.","note":"国語研では愛媛を含む四県の語。愛媛だけの語ではない。","noteEn":"NINJAL includes Ehime among four prefectures; not exclusive to Ehime.","sourceUrl":"https://kotoba.ninjal.ac.jp/qa/yokuaru/qa-236/","sourceTitle":"国立国語研究所ことば研究館「オノマトペにも方言がありますか」"},{"region":"nagasaki","phrase":"ドベドベ","reading":"Dobedobe","standard":"ぬかるんでいる様子","english":"Muddy; boggy.","scene":"雨・道","sceneEn":"Rain · paths","tag":"condition","register":"regional","registerEn":"regional","example":"A: 「ドベドベ」は乾いた道？ B: ぬかるんでいる様子のことだよ。","exampleEn":"A: Does “dobedobe” describe a dry path? B: It describes a muddy one.","note":"国語研は長崎・熊本などに記録。現代頻度の保証はしない。","noteEn":"NINJAL lists Nagasaki and Kumamoto, among others; frequency is not guaranteed.","sourceUrl":"https://kotoba.ninjal.ac.jp/qa/yokuaru/qa-236/","sourceTitle":"国立国語研究所ことば研究館「オノマトペにも方言がありますか」"},{"region":"kitakyushu","phrase":"グラグラ","reading":"Guragura","standard":"激怒する様子","english":"Extremely angry.","scene":"感情・聞き取り","sceneEn":"Feelings · listening","tag":"feeling","register":"regional","registerEn":"regional","example":"A: 怒っている話で「グラグラ」と聞いた。 B: 北九州地方では激怒する様子も表すよ。","exampleEn":"A: I heard “guragura” in an angry conversation. B: In northern Kyushu it can describe extreme anger.","note":"国語研の北九州地方（福岡・佐賀・大分）の用法。揺れる意味と区別。","noteEn":"NINJAL’s northern Kyushu usage; distinguish anger from physical wobbling.","sourceUrl":"https://kotoba.ninjal.ac.jp/qa/yokuaru/qa-236/","sourceTitle":"国立国語研究所ことば研究館「オノマトペにも方言がありますか」"},{"region":"miyakojima","phrase":"あすぱ","reading":"Asupa","standard":"遊ぼう","english":"Let us play.","scene":"友だち・語彙","sceneEn":"Friends · vocabulary","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 平良のことばで遊ぼうと言いたい。 B: 「あすぱ」という例があるよ。","exampleEn":"A: I want to say let us play in Hirara speech. B: One example is “asupa.”","note":"宮古語の平良言葉。例文はことばを引用した標準語会話。","noteEn":"Hirara Miyako language; the example quotes it within Japanese.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"miyakojima","phrase":"あがいたんでぃ","reading":"Agaitandi","standard":"やったー","english":"Hooray.","scene":"達成・喜び","sceneEn":"Achievement · joy","tag":"reaction","register":"regional","registerEn":"regional","example":"A: 平良言葉の喜びのことばは？ B: 読本には「あがいたんでぃ」があるよ。","exampleEn":"A: What is a joyful expression in Hirara speech? B: The textbook lists “agaitandi.”","note":"宮古語・平良の読本例。島内の全地域共通とはしない。","noteEn":"A Hirara Miyako example; not claimed for every part of the island.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"miyakojima","phrase":"あつぁやー","reading":"Atsa yā","standard":"明日ね","english":"See you tomorrow.","scene":"別れ・予定","sceneEn":"Farewells · plans","tag":"farewell","register":"regional","registerEn":"regional","example":"A: 平良言葉の「あつぁやー」を覚えたよ。 B: 明日ね、という意味だね。","exampleEn":"A: I learned Hirara’s “atsa yā.” B: That means see you tomorrow.","note":"宮古語・平良の例。ローマ字は音声の近似として読む。","noteEn":"Hirara Miyako; the romaji is an approximate reading.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"miyakojima","phrase":"いすか やりゃー","reading":"Isuka yaryā","standard":"いくらですか","english":"How much is it?","scene":"買い物・質問","sceneEn":"Shopping · questions","tag":"question","register":"regional","registerEn":"regional","example":"A: 平良の買い物ことばを習いたい。 B: 「いすか やりゃー」は、いくらですかの例だよ。","exampleEn":"A: I want to learn a Hirara shopping expression. B: “Isuka yaryā” is an example meaning how much is it.","note":"宮古語・平良の質問例。周囲の会話は標準語。","noteEn":"A Hirara Miyako question; the surrounding dialogue is standard Japanese.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"yaeyama","phrase":"あさば","reading":"Asaba","standard":"遊ぼう","english":"Let us play.","scene":"友だち・語彙","sceneEn":"Friends · vocabulary","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 石垣の四箇言葉を習っています。 B: 「あさば」は遊ぼうという意味だよ。","exampleEn":"A: I am learning Shika speech from Ishigaki. B: “Asaba” means let us play.","note":"八重山語・石垣市四箇の例。他の八重山の島へ一般化しない。","noteEn":"Shika Ishigaki Yaeyama language; not generalized to other Yaeyama islands.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"yaeyama","phrase":"あっぱー","reading":"Appā","standard":"お母さん","english":"Mother.","scene":"家族・語彙","sceneEn":"Family · vocabulary","tag":"daily","register":"regional","registerEn":"regional","example":"A: 四箇言葉の「あっぱー」は誰？ B: お母さんのことだよ。","exampleEn":"A: Who is “appā” in Shika speech? B: Mother.","note":"八重山語・石垣市四箇の家族語。引用した標準語会話の例。","noteEn":"A Shika Ishigaki family word, quoted within Japanese dialogue.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"yaeyama","phrase":"いこーびかやー","reading":"Ikōbikayā","standard":"いくらですか","english":"How much is it?","scene":"買い物・質問","sceneEn":"Shopping · questions","tag":"question","register":"regional","registerEn":"regional","example":"A: 四箇言葉で値段を聞く表現は？ B: 読本には「いこーびかやー」があるよ。","exampleEn":"A: How can you ask a price in Shika speech? B: The textbook lists “ikōbikayā.”","note":"八重山語・石垣市四箇の質問。ローマ字は近似。","noteEn":"A Shika Ishigaki Yaeyama question; romaji is approximate.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"okinawa-south","phrase":"うにげー さびら","reading":"Unigē sabira","standard":"お願いします","english":"Please; I ask your favor.","scene":"依頼・挨拶","sceneEn":"Requests · greetings","tag":"request","register":"regional","registerEn":"regional","example":"A: 那覇言葉の「うにげー さびら」を練習したい。 B: お願いします、という意味だよ。","exampleEn":"A: I want to practice Naha’s “unigē sabira.” B: It means please, or I ask your favor.","note":"沖縄語・那覇言葉。沖縄の日本語とは区別する。","noteEn":"Naha Okinawan language, distinct from Okinawan Japanese.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"okinawa-south","phrase":"うさがみそーれー","reading":"Usagamisōrē","standard":"召し上がれ・食べてください","english":"Please help yourself; please eat.","scene":"食事・勧め","sceneEn":"Meals · offers","tag":"invitation","register":"regional","registerEn":"regional","example":"A: 那覇の食事の挨拶を習いたい。 B: 「うさがみそーれー」は召し上がれという意味だよ。","exampleEn":"A: I want to learn a Naha mealtime expression. B: “Usagamisōrē” means please help yourself.","note":"沖縄語・那覇の丁寧な勧め。例は標準語で引用。","noteEn":"A polite Naha Okinawan offer, quoted inside standard Japanese.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"},{"region":"okinawa-south","phrase":"うじらーさん","reading":"Ujirāsan","standard":"かわいい","english":"Cute.","scene":"感想・語彙","sceneEn":"Reactions · vocabulary","tag":"compliment","register":"regional","registerEn":"regional","example":"A: 那覇言葉の「うじらーさん」はどんな感想？ B: かわいいという意味だよ。","exampleEn":"A: What reaction does Naha’s “ujirāsan” express? B: Cute.","note":"沖縄語・那覇言葉の読本例。南部全体の一律の語とはしない。","noteEn":"A Naha Okinawan example, not a uniform term across the entire south.","sourceUrl":"https://www.pref.okinawa.lg.jp/_res/projects/default_project/_page_/001/011/776/tokuhonchup86-124.pdf","sourceTitle":"沖縄県「しまくとぅば読本」索引 pp.100–124"}];
